/* ------------------------------ LAPORAN HARIAN + GAJI TUKANG ------------------------------ */
function v31WorkerAmount(status,dailyRate,otHours,otRate){const st=String(status||'HADIR').toUpperCase();const base=st==='HADIR'?num(dailyRate):st==='SETENGAH HARI'?num(dailyRate)*0.5:0;return base+num(otHours)*num(otRate);}
function v31WorkerRowHtml(w={}){const workers=(state.v31Workers||[]).filter(r=>String(r.data.status||'AKTIF').toUpperCase()!=='NONAKTIF');const selected=workers.find(x=>x.id===w.workerId);const daily=w.dailyRate??selected?.data.dailyRate??0;const otRate=w.overtimeRate??selected?.data.overtimeRate??0;const status=w.attendanceStatus||'HADIR';return `<div class="worker-row v31-grid-row"><select class="wr-worker" required><option value="">Pilih tukang</option>${workers.map(r=>`<option value="${esc(r.id)}" ${r.id===w.workerId?'selected':''}>${esc(r.data.name)} — ${esc(r.data.workerType||r.data.skill1||r.data.skill||'')}</option>`).join('')}</select><select class="wr-status"><option ${status==='HADIR'?'selected':''}>HADIR</option><option ${status==='SETENGAH HARI'?'selected':''}>SETENGAH HARI</option><option ${status==='IZIN'?'selected':''}>IZIN</option><option ${status==='SAKIT'?'selected':''}>SAKIT</option><option ${status==='ALPA'?'selected':''}>ALPA</option></select><input class="wr-rate" type="number" step="any" value="${esc(daily)}" placeholder="Upah harian"><input class="wr-ot-hours" type="number" step="any" min="0" value="${esc(w.overtimeHours||0)}" placeholder="Jam lembur"><input class="wr-ot-rate" type="number" step="any" value="${esc(otRate)}" placeholder="Tarif lembur"><input class="wr-total" value="${esc(v31WorkerAmount(status,daily,w.overtimeHours,otRate))}" readonly><button type="button" class="btn small danger wr-remove">×</button></div>`;}
function v31BindWorkerRows(){const box=$('#v31WorkerRows');if(!box)return;const recalc=row=>{const sel=$('.wr-worker',row);const worker=(state.v31Workers||[]).find(x=>x.id===sel.value);if(worker&&row.dataset.lastWorker!==sel.value){$('.wr-rate',row).value=num(worker.data.dailyRate);$('.wr-ot-rate',row).value=num(worker.data.overtimeRate);row.dataset.lastWorker=sel.value;}$('.wr-total',row).value=v31WorkerAmount($('.wr-status',row).value,$('.wr-rate',row).value,$('.wr-ot-hours',row).value,$('.wr-ot-rate',row).value);v31UpdatePayrollTotal();};$$('.worker-row',box).forEach(row=>{['change','input'].forEach(ev=>row.addEventListener(ev,()=>recalc(row)));$('.wr-remove',row).onclick=()=>{row.remove();v31UpdatePayrollTotal();};});}
function v31UpdatePayrollTotal(){const rows=$$('.worker-row','#v31WorkerRows');const total=rows.reduce((s,r)=>s+num($('.wr-total',r).value),0);if($('#v31WorkerCount'))$('#v31WorkerCount').textContent=rows.length;if($('#v31PayrollTotal'))$('#v31PayrollTotal').textContent=fmtRp(total);}
async function openDailyProgressForm(row=null){
  state.v31Workers=await loadCollection('tukang',false);const allWorkerRows=await loadCollection('daily_workers',false);const data=row?.data||{};let projectId=data.projectId||state.selectedProjectId||'';const workers=row?allWorkerRows.filter(x=>x.data.dailyProgressId===row.id).map(x=>x.data):[];const pid=v31AssignedPelaksana(projectId)||data.picUserId||'';
  const html=`<div class="form-grid"><label>Proyek<select name="projectId" id="v31DailyProject" required><option value="">Pilih proyek</option>${v31ProjectOptions(projectId)}</select></label><label>Tanggal<input name="date" type="date" value="${esc(data.date||new Date().toISOString().slice(0,10))}" required></label><label>Progress Aktual / Realisasi (%)<input name="progress" type="number" step="any" value="${esc(data.progress??'')}" required></label><label>Progress Rencana (%)<input name="planProgress" type="number" step="any" value="${esc(data.planProgress??'')}" required></label><label>PIC Laporan — Pelaksana Lapangan<input id="v31DailyPicName" value="${esc(employeeName(pid))}" readonly><input type="hidden" name="picUserId" id="v31DailyPic" value="${esc(pid)}"></label><label>Cuaca<input name="weather" value="${esc(data.weather||'')}"></label><label class="span-2">Pekerjaan Hari Ini<textarea name="work" required>${esc(data.work||'')}</textarea></label><label class="span-2">Kendala<textarea name="issue">${esc(data.issue||'')}</textarea></label><label class="span-2">Rencana Berikutnya<textarea name="nextPlan">${esc(data.nextPlan||'')}</textarea></label></div><div class="subsection"><div class="subsection-head"><div><h4>Tenaga Kerja Hari Ini</h4><p>Nama tukang dari Master ATI. Data ini otomatis menjadi rekap kehadiran dan upah.</p></div><button type="button" class="btn small primary" id="v31AddWorker">+ Tambah Tukang</button></div><div class="v31-worker-head"><span>Nama</span><span>Status</span><span>Upah Harian</span><span>Jam Lembur</span><span>Tarif Lembur</span><span>Total</span><span></span></div><div id="v31WorkerRows">${workers.map(v31WorkerRowHtml).join('')}</div><div class="payroll-total">Jumlah pekerja: <b id="v31WorkerCount">${workers.length}</b><span>Total upah hari ini: <b id="v31PayrollTotal">${fmtRp(workers.reduce((s,w)=>s+num(w.amount),0))}</b></span></div></div><label class="span-2">Lampiran progress (opsional)<input type="file" name="attachment"></label>`;
  openModal(row?'Edit Laporan Harian':'Tambah Laporan Harian','PIC dikunci ke Pelaksana Lapangan pada proyek. Kehadiran tukang langsung masuk Rekap Upah.',html,async form=>{
    const pId=form.projectId.value;const pelaksana=v31AssignedPelaksana(pId);if(!pelaksana)throw new Error('Proyek belum memiliki Pelaksana Lapangan. Isi penugasan proyek terlebih dahulu.');
    const wr=$$('.worker-row','#v31WorkerRows');const seen=new Set();const attendance=wr.map(r=>{const workerId=$('.wr-worker',r).value;if(!workerId)throw new Error('Pilih nama tukang pada semua baris.');if(seen.has(workerId))throw new Error('Nama tukang tidak boleh ganda pada laporan harian yang sama.');seen.add(workerId);const st=$('.wr-status',r).value;const rate=num($('.wr-rate',r).value);const oth=num($('.wr-ot-hours',r).value);const otr=num($('.wr-ot-rate',r).value);return {workerId,workerName:v31WorkerName(workerId),attendanceStatus:st,dailyRate:rate,overtimeHours:oth,overtimeRate:otr,amount:v31WorkerAmount(st,rate,oth,otr)};});
    const payload={projectId:pId,date:form.date.value,progress:num(form.progress.value),planProgress:num(form.planProgress.value),picUserId:pelaksana,manpower:attendance.filter(x=>!['ALPA','IZIN','SAKIT'].includes(x.attendanceStatus)).length,weather:form.weather.value,work:form.work.value,issue:form.issue.value,nextPlan:form.nextPlan.value};const id=row?.id||crypto.randomUUID();
    if(row)await api(`/api/records/daily_progress/${encodeURIComponent(id)}`,{method:'PUT',body:payload});else await api('/api/records/daily_progress',{method:'POST',body:{id,data:payload}});
    const old=allWorkerRows.filter(x=>x.data.dailyProgressId===id);for(const x of old)await api(`/api/records/daily_workers/${encodeURIComponent(x.id)}`,{method:'DELETE'});
    for(const a of attendance)await api('/api/records/daily_workers',{method:'POST',body:{id:crypto.randomUUID(),data:{...a,projectId:pId,dailyProgressId:id,date:payload.date,picUserId:pelaksana,status:'RECORDED'}}});
    const file=form.attachment.files?.[0];if(file)await uploadRelatedDocument(file,{projectId:pId,category:'OTHER',title:`Laporan Harian ${projectName(pId)} - ${payload.date}`,relatedCollection:'daily_progress',relatedId:id});toast('Laporan harian dan rekap upah tukang tersimpan.');await refreshAfterMutation();
  });
  $('#v31DailyProject').onchange=()=>{const id=$('#v31DailyProject').value;const pic=v31AssignedPelaksana(id);$('#v31DailyPic').value=pic;$('#v31DailyPicName').value=employeeName(pic);};
  $('#v31AddWorker').onclick=()=>{if(!(state.v31Workers||[]).length){toast('Tambahkan data tukang di ATI terlebih dahulu.','err');return;}$('#v31WorkerRows').insertAdjacentHTML('beforeend',v31WorkerRowHtml({}));v31BindWorkerRows();v31UpdatePayrollTotal();};v31BindWorkerRows();v31UpdatePayrollTotal();
}

renderProgress = async function(){
  const scope=Boolean(state.selectedProjectId);state.v31Workers=await loadCollection('tukang',false);const [daily,dailyWorkers,weekly,schedule,milestones,issues]=await Promise.all([loadCollection('daily_progress',scope),loadCollection('daily_workers',scope),loadCollection('weekly_progress',scope),loadCollection('schedule',scope),loadCollection('milestones',scope),loadCollection('issues',scope)]);
  const payrollTotal=dailyWorkers.reduce((s,r)=>s+num(r.data.amount),0);const dailyTable=`<div class="card"><div class="card-head"><div><h3>Laporan Harian Lapangan</h3><p>PIC selalu Pelaksana Lapangan. Nama tukang di laporan ini otomatis masuk rekap gaji.</p></div>${canCollection('daily_progress','create')?'<div class="card-actions"><button class="btn primary" id="v31AddDaily">+ Laporan Harian</button></div>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Proyek</th><th>Pelaksana</th><th>Pekerjaan</th><th>Aktual</th><th>Rencana</th><th>Tukang</th><th></th></tr></thead><tbody>${daily.map(r=>{const cnt=dailyWorkers.filter(x=>x.data.dailyProgressId===r.id).length;return `<tr><td>${fmtDate(r.data.date)}</td><td><b>${esc(projectName(r.data.projectId))}</b></td><td>${esc(employeeName(r.data.picUserId))}</td><td>${esc(r.data.work||'-')}</td><td>${fmtNum(r.data.progress)}%</td><td>${fmtNum(r.data.planProgress)}%</td><td>${cnt}</td><td class="actions">${canCollection('daily_progress','update')?`<button class="btn small" data-daily-edit="${esc(r.id)}">Edit</button>`:''}</td></tr>`}).join('')||'<tr><td colspan="8" class="empty">Belum ada laporan harian.</td></tr>'}</tbody></table></div></div>`;
  const wage=`<div class="card"><div class="card-head"><div><h3>Rekap Kehadiran & Gaji Tukang</h3><p>Terbentuk otomatis dari daftar tukang pada laporan harian.</p></div><div class="pill green">Total ${fmtRp(payrollTotal)}</div></div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Proyek</th><th>Nama Tukang</th><th>Status</th><th>Upah Harian</th><th>Lembur</th><th>Total</th></tr></thead><tbody>${dailyWorkers.sort((a,b)=>String(b.data.date||'').localeCompare(String(a.data.date||''))).map(r=>`<tr><td>${fmtDate(r.data.date)}</td><td>${esc(projectName(r.data.projectId))}</td><td><b>${esc(r.data.workerName||v31WorkerName(r.data.workerId))}</b></td><td>${statusPill(r.data.attendanceStatus)}</td><td class="num">${fmtRp(r.data.dailyRate)}</td><td>${fmtNum(r.data.overtimeHours)} jam × ${fmtRp(r.data.overtimeRate)}</td><td class="num"><b>${fmtRp(r.data.amount)}</b></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Belum ada rekap upah.</td></tr>'}</tbody></table></div></div>`;
  $('#content').innerHTML=`<div class="notice green">Grafik Dashboard tetap memakai Progress Rencana dan Aktual/Realisasi. Laporan harian sekarang juga menjadi sumber absensi/upah tukang.</div>${dailyTable}${wage}${genericTable('weekly_progress',weekly,'Progress Mingguan','PIC dibatasi Pelaksana Lapangan.')}${genericTable('schedule',schedule,'Schedule / Kurva-S','PIC pelaksanaan dibatasi Pelaksana Lapangan.')}${genericTable('milestones',milestones,'Milestone','Target penting proyek.')}${genericTable('issues',issues,'Masalah & Corrective Action','PIC tindak lanjut lapangan dibatasi Pelaksana.')}`;bindCrudActions();if($('#v31AddDaily'))$('#v31AddDaily').onclick=()=>openDailyProgressForm();$$('[data-daily-edit]').forEach(b=>b.onclick=()=>openDailyProgressForm(daily.find(x=>x.id===b.dataset.dailyEdit)));
};

/* ------------------------------ PROCUREMENT / MULTI ITEM PR ------------------------------ */
function v31PrItemRow(x={}){return `<div class="pr-item-row v31-pr-item"><input class="pi-desc" value="${esc(x.description||'')}" placeholder="Spesifikasi material/jasa" required><input class="pi-qty" type="number" step="any" value="${esc(x.qty??1)}" placeholder="Vol"><input class="pi-unit" value="${esc(x.unit||'Unit')}" placeholder="Sat"><input class="pi-hpp" type="number" step="any" value="${esc(x.hppUnit??0)}" placeholder="HPP/Unit"><input class="pi-total" value="${esc(x.totalHpp??num(x.qty)*num(x.hppUnit))}" readonly><button type="button" class="btn small danger pi-remove">×</button></div>`;}
function v31VendorRow(x={}){return `<div class="pr-vendor-row v31-pr-vendor"><input class="pv-vendor-name" value="${esc(x.vendorName||'')}" placeholder="Ketik nama vendor" required><input class="pv-amount" type="number" step="any" value="${esc(x.amount??0)}" placeholder="Total penawaran"><input class="pv-term" value="${esc(x.term||'')}" placeholder="Term pembayaran"><input class="pv-lead" value="${esc(x.leadTime||'')}" placeholder="Lead time"><input class="pv-note" value="${esc(x.notes||'')}" placeholder="Catatan"><input class="pv-file" type="file" accept=".pdf,image/*" title="Quotation opsional"><button type="button" class="btn small danger pv-remove">×</button></div>`;}
function v31BindPrRows(){const recalc=()=>{let total=0;$$('.v31-pr-item','#v31PrItems').forEach(r=>{const t=num($('.pi-qty',r).value)*num($('.pi-hpp',r).value);$('.pi-total',r).value=t;total+=t;});if($('#v31PrHppTotal'))$('#v31PrHppTotal').textContent=fmtRp(total);};$$('.v31-pr-item','#v31PrItems').forEach(r=>{r.oninput=recalc;$('.pi-remove',r).onclick=()=>{r.remove();recalc();};});$$('.v31-pr-vendor','#v31PrVendors').forEach(r=>{$('.pv-remove',r).onclick=()=>r.remove();});recalc();}
function v31ReadPrItems(){return $$('.v31-pr-item','#v31PrItems').map(r=>({id:crypto.randomUUID(),description:$('.pi-desc',r).value.trim(),qty:num($('.pi-qty',r).value),unit:$('.pi-unit',r).value,hppUnit:num($('.pi-hpp',r).value),totalHpp:num($('.pi-total',r).value)})).filter(x=>x.description);}
function v31ReadVendorOffers(){return $$('.v31-pr-vendor','#v31PrVendors').map(r=>({id:r.dataset.offerId||crypto.randomUUID(),vendorId:'',vendorName:$('.pv-vendor-name',r).value.trim(),vendorVmlId:'',amount:num($('.pv-amount',r).value),term:$('.pv-term',r).value.trim(),leadTime:$('.pv-lead',r).value.trim(),notes:$('.pv-note',r).value.trim()})).filter(x=>x.vendorName);}
function v31DefaultPrNumber(){const d=new Date();return `PR-${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}-${String(Date.now()).slice(-6)}`;}
async function openPrForm(row=null){state.v31Vendors=[];const d=row?.data||{};if(!d.prNumber)d.prNumber=v31DefaultPrNumber();const projectId=d.projectId||state.selectedProjectId||'';const pm=v31AssignedPm(projectId);const fieldRequester=['project_manager','pelaksana_lapangan'].includes(state.access?.roleKey)?state.user.id:'';const requester=d.requesterUserId||fieldRequester||pm;const items=Array.isArray(d.items)?d.items:[];const offers=Array.isArray(d.vendorOffers)?d.vendorOffers:[];const html=`<div class="form-grid"><label>No. PR<input name="prNumber" value="${esc(d.prNumber||'')}" required></label><label>Nama Proyek<select name="projectId" id="v31PrProject" required><option value="">Pilih proyek</option>${v31ProjectOptions(projectId)}</select></label><label>Tanggal PR<input name="date" type="date" value="${esc(d.date||new Date().toISOString().slice(0,10))}" required></label><label>Pengaju PR<input id="v31PrRequester" value="${esc(employeeName(requester)||state.user.name||'')}" readonly></label><label>Project Manager<input id="v31PrPm" value="${esc(employeeName(pm))}" readonly></label><label>Lokasi Penerimaan<input name="deliveryLocation" value="${esc(d.deliveryLocation||v31Project(projectId)?.data.location||'')}"></label><label>Durasi Pekerjaan — Mulai<input name="workStartDate" type="date" value="${esc(d.workStartDate||'')}"></label><label>Durasi Pekerjaan — Selesai<input name="workEndDate" type="date" value="${esc(d.workEndDate||'')}"></label></div><div class="subsection"><div class="subsection-head"><div><h4>Daftar Material / Jasa — HPP Detail</h4><p>Satu PR dapat berisi banyak item pekerjaan/material/jasa.</p></div><button type="button" id="v31AddPrItem" class="btn small primary">+ Tambah Item</button></div><div class="pr-item-head"><span>Spesifikasi Material/Jasa</span><span>Vol</span><span>Sat</span><span>HPP/Unit</span><span>Total HPP</span><span></span></div><div id="v31PrItems">${items.map(v31PrItemRow).join('')}</div><div class="payroll-total">TOTAL HPP <b id="v31PrHppTotal">${fmtRp(d.totalHpp||0)}</b></div></div><div class="subsection"><div class="subsection-head"><div><h4>Evaluasi Vendor</h4><p>Bisa menambahkan lebih dari satu vendor. Head of Operational/Head Unit Bisnis memilih vendor setelah PR diajukan.</p></div><button type="button" id="v31AddVendor" class="btn small primary">+ Tambah Vendor</button></div><div class="pr-vendor-head"><span>Nama Vendor</span><span>Total Penawaran</span><span>Term</span><span>Lead Time</span><span>Catatan</span><span>Quotation (Opsional)</span><span></span></div><div id="v31PrVendors">${offers.map(x=>{const h=v31VendorRow(x);return h.replace('class="pr-vendor-row v31-pr-vendor"',`class="pr-vendor-row v31-pr-vendor" data-offer-id="${esc(x.id||'')}"`)}).join('')}</div></div><label class="coi-box"><input type="checkbox" name="coiDeclaration" ${d.coiDeclaration?'checked':''}> <span><b>Deklarasi Conflict of Interest</b><br>Saya sebagai pengaju PR menyatakan tidak memiliki hubungan keluarga, kepemilikan, kepentingan finansial, maupun bentuk Conflict of Interest lainnya dengan vendor yang masuk evaluasi PR ini.</span></label><label>Catatan PR<textarea name="notes">${esc(d.notes||'')}</textarea></label>`;
  openModal(row?'Edit Purchase Request':'Buat Purchase Request','Struktur: header proyek/durasi → multi-item HPP → multi-vendor → deklarasi COI → submit → pemilihan vendor.',html,async form=>{const items=v31ReadPrItems();if(!items.length)throw new Error('Minimal satu item material/jasa wajib diisi.');const vendorOffers=v31ReadVendorOffers();const pId=form.projectId.value;const assignedPm=v31AssignedPm(pId);if(!assignedPm)throw new Error('Proyek belum memiliki Project Manager. Tetapkan PM pada Master Proyek terlebih dahulu.');const requesterId=d.requesterUserId||(['project_manager','pelaksana_lapangan'].includes(state.access?.roleKey)?state.user.id:assignedPm);const payload={prNumber:form.prNumber.value,projectId:pId,date:form.date.value,requesterUserId:requesterId,projectManagerUserId:assignedPm,deliveryLocation:form.deliveryLocation.value,workStartDate:form.workStartDate.value,workEndDate:form.workEndDate.value,items,vendorOffers,totalHpp:items.reduce((s,x)=>s+x.totalHpp,0),coiDeclaration:form.coiDeclaration.checked,notes:form.notes.value};const id=row?.id||crypto.randomUUID();if(row)await api(`/api/records/procurement/${encodeURIComponent(id)}`,{method:'PUT',body:payload});else await api('/api/records/procurement',{method:'POST',body:{id,data:payload}});const vendorRows=$$('.v31-pr-vendor','#v31PrVendors');for(let i=0;i<vendorRows.length;i++){const file=$('.pv-file',vendorRows[i]).files?.[0];if(file)await uploadRelatedDocument(file,{projectId:pId,category:'OTHER',title:`Penawaran Vendor PR - ${vendorOffers[i]?.vendorName||'Vendor'}`,relatedCollection:'procurement',relatedId:id});}toast('Purchase Request tersimpan.');await refreshAfterMutation();});
  $('#v31PrProject').onchange=()=>{const p=$('#v31PrProject').value;const newPm=v31AssignedPm(p);$('#v31PrPm').value=employeeName(newPm);if(!row&&!['project_manager','pelaksana_lapangan'].includes(state.access?.roleKey))$('#v31PrRequester').value=employeeName(newPm);};$('#v31AddPrItem').onclick=()=>{$('#v31PrItems').insertAdjacentHTML('beforeend',v31PrItemRow({}));v31BindPrRows();};$('#v31AddVendor').onclick=()=>{$('#v31PrVendors').insertAdjacentHTML('beforeend',v31VendorRow({}));v31BindPrRows();};v31BindPrRows();
}
async function openPrDecision(row){const d=row.data;const offers=Array.isArray(d.vendorOffers)?d.vendorOffers:[];if(!offers.length){toast('Belum ada penawaran vendor. Procurement/Admin harus melengkapi pembanding vendor terlebih dahulu.','err');return;}const html=`<div class="notice blue"><b>${esc(projectName(d.projectId))}</b><br>Total HPP: ${fmtRp(d.totalHpp)}</div><div class="table-wrap"><table class="table"><thead><tr><th>Pilih</th><th>Vendor</th><th>Penawaran</th><th>Selisih vs HPP</th><th>Term</th><th>Lead Time</th></tr></thead><tbody>${offers.map((v,i)=>`<tr><td><input type="radio" name="vendorOfferId" value="${esc(v.id)}" ${i===0?'checked':''}></td><td><b>${esc(v.vendorName||'-')}</b></td><td class="num">${fmtRp(v.amount)}</td><td class="num">${fmtRp(num(v.amount)-num(d.totalHpp))}</td><td>${esc(v.term||'-')}</td><td>${esc(v.leadTime||'-')}</td></tr>`).join('')}</tbody></table></div>`;openModal('Pilih Vendor PR','Keputusan vendor hanya tersedia untuk Head of Operational atau Head Unit Bisnis.',html,async form=>{const selected=form.querySelector('input[name="vendorOfferId"]:checked')?.value;if(!selected)throw new Error('Pilih vendor.');await api(`/api/procurement/${encodeURIComponent(row.id)}/action`,{method:'POST',body:{action:'select-vendor',vendorOfferId:selected}});toast('Vendor terpilih dan PR disetujui.');state.cache.clear();await renderProcurement();});}
function v31PrActions(r){const s=String(r.data.status||'DRAFT').toUpperCase();let x=`<button class="btn small" data-pr-detail="${esc(r.id)}">Detail</button>`;if(canCollection('procurement','update')&&(['DRAFT','REJECTED'].includes(s)||(s==='SUBMITTED'&&['procurement','manager_operasional','admin_teknik','administrator','direktur','head_unit_bisnis'].includes(state.access.roleKey))))x+=`<button class="btn small" data-pr-edit="${esc(r.id)}">Edit/Lengkapi</button>`;if(['DRAFT','REJECTED'].includes(s)&&(String(r.data.requesterUserId||'')===String(state.user.id)||['manager_operasional','head_unit_bisnis'].includes(state.access.roleKey)))x+=`<button class="btn small primary" data-pr-action="submit" data-id="${esc(r.id)}">Submit</button>`;if(cap('procurementVendorSelect')&&s==='SUBMITTED')x+=`<button class="btn small success" data-pr-select="${esc(r.id)}">Pilih Vendor</button><button class="btn small danger" data-pr-action="reject" data-id="${esc(r.id)}">Reject</button>`;if(canCollection('po','create')&&s==='APPROVED')x+=`<button class="btn small accent" data-create-po="${esc(r.id)}">Buat PO/SPK</button>`;if(cap('procurementOrder')&&s==='APPROVED')x+=`<button class="btn small" data-pr-action="order" data-id="${esc(r.id)}">Ordered</button>`;if(cap('procurementOrder')&&s==='ORDERED')x+=`<button class="btn small success" data-pr-action="receive" data-id="${esc(r.id)}">Diterima</button>`;return x;}
function openPrDetail(r){const d=r.data;openModal('Detail Purchase Request',`${projectName(d.projectId)} • ${fmtDate(d.date)}`,`<div class="info-grid"><div class="info-card"><b>Total HPP</b><div class="big-number">${fmtRp(d.totalHpp)}</div></div><div class="info-card"><b>Vendor Terpilih</b><div>${esc(d.selectedVendorName||'Belum dipilih')}</div><div class="muted">${d.selectedOfferAmount?fmtRp(d.selectedOfferAmount):''}</div></div></div><h4>Daftar Material/Jasa</h4><div class="table-wrap"><table class="table"><thead><tr><th>No</th><th>Spesifikasi</th><th>Vol</th><th>Sat</th><th>HPP/Unit</th><th>Total HPP</th></tr></thead><tbody>${(d.items||[]).map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.description)}</td><td>${fmtNum(x.qty)}</td><td>${esc(x.unit)}</td><td class="num">${fmtRp(x.hppUnit)}</td><td class="num">${fmtRp(x.totalHpp)}</td></tr>`).join('')}</tbody></table></div><h4 style="margin-top:18px">Evaluasi Vendor</h4><div class="table-wrap"><table class="table"><thead><tr><th>Vendor</th><th>Penawaran</th><th>Term</th><th>Lead Time</th></tr></thead><tbody>${(d.vendorOffers||[]).map(v=>`<tr class="${v.id===d.selectedVendorOfferId?'selected-row':''}"><td>${esc(v.vendorName)}</td><td class="num">${fmtRp(v.amount)}</td><td>${esc(v.term||'-')}</td><td>${esc(v.leadTime||'-')}</td></tr>`).join('')||'<tr><td colspan="4">Belum ada vendor.</td></tr>'}</tbody></table></div><div class="notice ${d.coiDeclaration?'green':'orange'}" style="margin-top:14px">Deklarasi Conflict of Interest: <b>${d.coiDeclaration?'Disetujui':'Belum disetujui'}</b></div>`,async()=>{});}

renderProcurement = async function(){state.v31Vendors=[];const [prs,pos]=await Promise.all([loadCollection('procurement',Boolean(state.selectedProjectId)),loadCollection('po',Boolean(state.selectedProjectId))]);$('#content').innerHTML=`<div class="info-grid"><div class="info-card"><span class="tag manual">Purchase Request</span><h4>Multi-item + HPP</h4><p>Satu PR dapat memuat banyak material/jasa. HPP dihitung per item: Vol × HPP/Unit, lalu ditotal.</p></div><div class="info-card"><span class="tag auto">Vendor Comparison</span><h4>Lebih dari satu vendor</h4><p>Project Manager mengetik pembanding vendor langsung. Head of Operational/Head Unit Bisnis memilih vendor berdasarkan harga, term, lead time, dan pertimbangan operasional.</p></div></div><div class="card"><div class="card-head"><div><h3>Purchase Request (PR)</h3><p>Project Manager membuat PR dan mengetik pembanding vendor langsung; Head of Operational/Head Unit Bisnis memilih vendor.</p></div>${canCollection('procurement','create')?'<div class="card-actions"><button class="btn primary" id="v31NewPr">+ Buat PR</button></div>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>No. PR</th><th>Tanggal</th><th>Nama Proyek</th><th>Pengaju</th><th>PM</th><th>Item</th><th>Total HPP</th><th>Vendor Pembanding</th><th>Vendor Terpilih</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${prs.map(r=>`<tr><td><b>${esc(r.data.prNumber||'-')}</b></td><td>${fmtDate(r.data.date)}</td><td><b>${esc(projectName(r.data.projectId))}</b></td><td>${esc(employeeName(r.data.requesterUserId)||'-')}</td><td>${esc(employeeName(r.data.projectManagerUserId||v31AssignedPm(r.data.projectId)))}</td><td>${(r.data.items||[]).length}</td><td class="num">${fmtRp(r.data.totalHpp)}</td><td>${(r.data.vendorOffers||[]).length}</td><td>${esc(r.data.selectedVendorName||'-')}</td><td>${statusPill(r.data.status||'DRAFT')}</td><td class="actions">${v31PrActions(r)}</td></tr>`).join('')||'<tr><td colspan="11" class="empty">Belum ada PR.</td></tr>'}</tbody></table></div></div>${poTable(pos)}`;bindCrudActions();bindWorkflowButtons();if($('#v31NewPr'))$('#v31NewPr').onclick=()=>openPrForm();$$('[data-pr-edit]').forEach(b=>b.onclick=()=>openPrForm(prs.find(x=>x.id===b.dataset.prEdit)));$$('[data-pr-select]').forEach(b=>b.onclick=()=>openPrDecision(prs.find(x=>x.id===b.dataset.prSelect)));$$('[data-pr-detail]').forEach(b=>b.onclick=()=>openPrDetail(prs.find(x=>x.id===b.dataset.prDetail)));};

/* ------------------------------ QC MANAGEMENT SYSTEM ------------------------------ */
const V31_QC_AREAS=['Struktur','Dinding','Plafond','Lantai','Kusen Jendela','Pintu','Toilet','Kitchen','MEP','Interior','Eksterior','Lainnya'];
const V31_QC_CATS=['Struktur','Arsitektur','Finishing','MEP','Interior','Fungsi','Kerapian','Material','Lainnya'];
function v31QcScore(rows){if(!rows.length)return 100;const weight={MINOR:1,MAJOR:2,CRITICAL:3,'C - MINOR':1,'B - MAYOR':2,'A - KRITIS':3};let total=0,got=0;for(const r of rows){const w=weight[String(r.data.severity||'MINOR').toUpperCase()]||1;total+=w;if(String(r.data.status).toUpperCase()==='CLOSED'){const late=r.data.deadline&&r.data.closedAt&&String(r.data.closedAt).slice(0,10)>String(r.data.deadline);got+=w*(late?.6:1);}}return total?Math.round(got/total*100):100;}
async function openQcFindingForm(existing=null){
  const row=existing||null,d=row?.data||{},isEdit=Boolean(row);
  const pId=d.projectId||state.selectedProjectId||'';
  const selected=(value,target)=>String(value||'')===String(target||'')?' selected':'';
  const html=`<div class="form-grid">
    <label>Proyek<select name="projectId" id="v31QcProject" required ${isEdit?'disabled':''}><option value="">Pilih proyek</option>${v31ProjectOptions(pId)}</select></label>
    <label>Tanggal Inspeksi<input type="date" name="date" value="${esc(d.date||new Date().toISOString().slice(0,10))}" required></label>
    <label>Area<input name="area" list="v31QcAreas" value="${esc(d.area||d.item||'')}" required><datalist id="v31QcAreas">${V31_QC_AREAS.map(x=>`<option value="${esc(x)}">`).join('')}</datalist></label>
    <label>Kategori<input name="category" list="v31QcCats" value="${esc(d.category||'')}" required><datalist id="v31QcCats">${V31_QC_CATS.map(x=>`<option value="${esc(x)}">`).join('')}</datalist></label>
    <label>Severity<select name="severity" required><option value="C - MINOR"${selected(d.severity||'C - MINOR','C - MINOR')}>C - MINOR</option><option value="B - MAYOR"${selected(d.severity,'B - MAYOR')}>B - MAYOR</option><option value="A - KRITIS"${selected(d.severity,'A - KRITIS')}>A - KRITIS</option></select></label>
    <label>Deadline Perbaikan<input type="date" name="deadline" value="${esc(d.deadline||'')}" required></label>
    <label>PIC Penanggung Jawab — Pelaksana<select name="picUserId" id="v31QcPic" required><option value="">Pilih Pelaksana</option>${v31EmployeeOptions(['pelaksana_lapangan'],d.picUserId||v31AssignedPelaksana(pId))}</select></label>
    <label class="span-2">Deskripsi Temuan<textarea name="description" required placeholder="Jelaskan ketidaksesuaian yang ditemukan, acuan spesifikasi, dan dampaknya.">${esc(d.description||d.notes||'')}</textarea></label>
    <label class="span-2">Saran Perbaikan<textarea name="suggestion" placeholder="Metode perbaikan yang disarankan dan hasil akhir yang diharapkan.">${esc(d.suggestion||'')}</textarea></label>
    <label class="span-2">${isEdit?'Tambah Bukti / Foto Before Baru (opsional)':'Foto Temuan / Before'}<input type="file" name="file" accept="image/*" ${isEdit?'':'required'}></label>
  </div>`;
  openModal(isEdit?'Edit Temuan QC':'Buat Temuan QC',isEdit?'Status workflow tidak diubah dari form ini. Gunakan tombol Mulai/Kirim Perbaikan/Verifikasi untuk perpindahan tahap.':'Temuan + PIC + deadline + bukti before. Setelah dibuat, tugas perbaikan masuk ke Pelaksana.',html,async form=>{
    const p=isEdit?d.projectId:form.projectId.value;
    const assigned=v31AssignedPelaksana(p),pic=form.picUserId.value;
    if(pic!==assigned&&assigned)throw new Error('PIC temuan harus Pelaksana Lapangan yang menangani proyek.');
    const payload={date:form.date.value,area:form.area.value,item:form.area.value,category:form.category.value,severity:form.severity.value,picUserId:pic,deadline:form.deadline.value,description:form.description.value,suggestion:form.suggestion.value};
    let id=row?.id;
    if(isEdit){await api(`/api/qc/findings/${encodeURIComponent(id)}`,{method:'PATCH',body:payload});}
    else{id=crypto.randomUUID();await api('/api/records/defects',{method:'POST',body:{id,data:{projectId:p,...payload,status:'OPEN'}}});}
    const file=form.file.files?.[0];
    if(file)await uploadRelatedDocument(file,{projectId:p,category:'QC_EVIDENCE',title:`QC Before - ${payload.area} - ${payload.date}`,relatedCollection:'defects',relatedId:id});
    toast(isEdit?'Temuan QC diperbarui.':'Temuan QC diterbitkan dan ditugaskan ke Pelaksana.');state.cache.clear();await renderQc();
  });
  if(!isEdit)$('#v31QcProject').onchange=()=>{const id=v31AssignedPelaksana($('#v31QcProject').value);$('#v31QcPic').value=id||'';};
}
async function deleteQcFinding(row){
  if(!row)return;if(!(await confirmAsk(`Hapus temuan QC “${row.data.area||row.data.item||'-'}”? Riwayat perbaikan/verifikasi terkait juga akan dihapus, tetapi audit penghapusan tetap tersimpan.`)))return;
  try{await api(`/api/qc/findings/${encodeURIComponent(row.id)}`,{method:'DELETE'});toast('Temuan QC dihapus.');state.cache.clear();await renderQc();}catch(e){toast(e.message,'err');}
}
async function openQcSessionEdit(row){
  if(!row)return;const d=row.data||{};const html=`<div class="form-grid"><label>Tanggal Mulai<input name="startDate" type="date" value="${esc(d.startDate||'')}" required></label><label class="span-2">Catatan Pemeriksaan<textarea name="note" placeholder="Catatan umum inspeksi">${esc(d.note||'')}</textarea></label></div>`;
  openModal('Edit Catatan Inspeksi QC',`${projectName(d.projectId)} • hanya catatan yang masih Berjalan dapat diedit.`,html,async form=>{await api(`/api/qc/sessions/${encodeURIComponent(row.id)}`,{method:'PATCH',body:{startDate:form.startDate.value,note:form.note.value}});toast('Catatan inspeksi diperbarui.');state.cache.clear();await renderQc();});
}
async function deleteQcSessionFromList(row){
  if(!row)return;if(!(await confirmAsk(`Hapus seluruh catatan inspeksi ${projectName(row.data.projectId)}? Sub-pekerjaan dan temuan yang berasal dari catatan ini ikut dihapus. Audit penghapusan tetap tersimpan.`)))return;
  try{await api(`/api/qc/sessions/${encodeURIComponent(row.id)}`,{method:'DELETE'});toast('Catatan inspeksi dan data terkait dihapus.');state.cache.clear();await renderQc();}catch(e){toast(e.message,'err');}
}
async function openQcItemEdit(sessionId,itemRow){
  if(!itemRow)return;const d=itemRow.data||{},locked=Boolean(d.findingId);closeModal();
  const html=`<div class="form-grid"><label class="span-2">Uraian Sub-pekerjaan<input name="item" value="${esc(d.item||'')}" required></label><label>Tanggal Pemeriksaan<input name="date" type="date" value="${esc(d.date||'')}" required></label><label>Hasil<select name="result" ${locked?'disabled':''}><option value="SESUAI" ${String(d.result).toUpperCase()==='SESUAI'?'selected':''}>Sesuai</option><option value="TIDAK SESUAI" ${String(d.result).toUpperCase()==='TIDAK SESUAI'?'selected':''}>Tidak sesuai</option></select></label><label class="span-2">Keterangan<textarea name="note">${esc(d.note||'')}</textarea></label></div>${locked?'<div class="notice orange">Hasil tidak dapat diubah menjadi Sesuai karena sub-pekerjaan sudah diterbitkan menjadi Temuan QC. Selesaikan melalui alur perbaikan dan verifikasi.</div>':''}`;
  openModal('Edit Sub-pekerjaan QC',`${esc(d.workGroup||'-')} • ${projectName(d.projectId)}`,html,async form=>{const body={item:form.item.value,date:form.date.value,note:form.note.value};if(!locked)body.result=form.result.value;await api(`/api/qc/session-items/${encodeURIComponent(itemRow.id)}`,{method:'PATCH',body});toast('Sub-pekerjaan QC diperbarui.');setTimeout(()=>openQcContinuousSession(sessionId),30);});
}
async function v31QcAction(id,action){if(action==='start')return simpleAction(`/api/qc/findings/${encodeURIComponent(id)}/action`,'start');if(action==='submit-fix'){const html=`<label>Uraian Hasil Perbaikan<textarea name="description" required></textarea></label><label>Foto Hasil Perbaikan / After<input type="file" name="file" accept="image/*" required></label>`;openModal('Kirim Hasil Perbaikan','Bukti foto after wajib. Setelah dikirim, status menjadi WAITING QC CHECK.',html,async form=>{const fd=new FormData();fd.append('action','submit-fix');fd.append('description',form.description.value);fd.append('file',form.file.files[0]);await api(`/api/qc/findings/${encodeURIComponent(id)}/action`,{method:'POST',body:fd});toast('Hasil perbaikan dikirim ke QC.');state.cache.clear();await renderQc();});return;}if(action==='verify'){const html=`<label>Hasil Pemeriksaan<select name="result" id="v31VerifyResult"><option value="SESUAI">Sesuai — tutup temuan</option><option value="TIDAK SESUAI">Tidak sesuai — kembalikan untuk revisi</option></select></label><label>Catatan QC<textarea name="note" placeholder="Wajib jika tidak sesuai."></textarea></label>`;openModal('Verifikasi Temuan','QC memutuskan sesuai atau perlu revisi.',html,async form=>{await api(`/api/qc/findings/${encodeURIComponent(id)}/action`,{method:'POST',body:{action:'verify',result:form.result.value,note:form.note.value}});toast(form.result.value==='SESUAI'?'Temuan CLOSED.':'Temuan dikembalikan untuk revisi.');state.cache.clear();await renderQc();});}}
function qcDocIsImage(doc){
  const d=doc?.data||{};const mime=String(d.mimeType||'').toLowerCase();const name=String(d.originalName||d.title||'').toLowerCase();
  return mime.startsWith('image/')||/\.(png|jpe?g|webp|gif|bmp|heic|heif)$/i.test(name);
}
function qcEvidencePanel(kind,doc,{date='',note='',empty='' }={}){
  const isBefore=kind==='BEFORE';const label=isBefore?'BEFORE':'AFTER';const subtitle=isBefore?'Kondisi sebelum perbaikan':'Hasil setelah perbaikan';
  const url=doc?`/api/documents/${encodeURIComponent(doc.id)}/file`:'';
  const media=doc?(qcDocIsImage(doc)?`<a class="qc-ba-image-link" href="${url}" target="_blank"><img src="${url}" alt="Foto ${label}" loading="lazy"></a>`:`<a class="qc-ba-file" href="${url}" target="_blank"><b>Buka bukti</b><span>${esc(doc.data?.originalName||doc.data?.title||'Dokumen')}</span></a>`):`<div class="qc-ba-empty"><b>${esc(empty||`Belum ada foto ${label.toLowerCase()}`)}</b><span>${isBefore?'Upload foto ketika membuat temuan/inspeksi.':'Pelaksana wajib mengirim foto hasil perbaikan.'}</span></div>`;
  return `<section class="qc-ba-card ${isBefore?'before':'after'}"><header><div><span class="qc-ba-tag">${label}</span><h4>${subtitle}</h4></div>${date?`<small>${fmtDate(date)}</small>`:''}</header>${media}<div class="qc-ba-note"><b>Catatan</b><p>${esc(note||'-')}</p></div></section>`;
}
async function openQcDetail(r){
  const acts=await loadCollection('qc_actions',true);const ver=await loadCollection('qc_verifications',true);const docs=(await api(`/api/documents?projectId=${encodeURIComponent(r.data.projectId)}`)).documents||[];const d=r.data;
  const findingActs=acts.filter(x=>x.data.findingId===r.id);const findingVer=ver.filter(x=>x.data.findingId===r.id);const actionIds=new Set(findingActs.map(x=>x.id));const related=docs.filter(x=>x.data.relatedId===r.id||actionIds.has(x.data.relatedId)||x.id===d.lastFixDocumentId||x.id===d.beforeDocumentId);
  const docById=new Map(docs.map(x=>[x.id,x]));
  const beforeDoc=docById.get(d.beforeDocumentId)||related.find(x=>/^QC Before/i.test(String(x.data.title||'')))||related.find(x=>x.data.relatedCollection==='defects'&&x.data.relatedId===r.id)||null;
  const latestFix=[...findingActs].reverse().find(x=>x.data.afterDocumentId)||null;const afterId=d.lastFixDocumentId||latestFix?.data?.afterDocumentId||'';const afterDoc=docById.get(afterId)||related.find(x=>x.id===afterId)||null;
  const beforeNote=d.description||d.notes||'';const afterNote=d.lastFixNote||latestFix?.data?.description||'';const beforeDate=d.date||beforeDoc?.data?.uploadedAt||'';const afterDate=d.submittedFixAt||latestFix?.data?.date||afterDoc?.data?.uploadedAt||'';
  const extraDocs=related.filter(x=>x.id!==beforeDoc?.id&&x.id!==afterDoc?.id);
  const html=`<div class="detail-grid"><dl><dt>Status</dt><dd>${statusPill(d.status)}</dd><dt>Kategori</dt><dd>${esc(d.category||'-')}</dd><dt>Severity</dt><dd>${esc(d.severity||'-')}</dd><dt>PIC</dt><dd>${esc(employeeName(d.picUserId))}</dd><dt>Deadline</dt><dd>${fmtDate(d.deadline)}</dd></dl><div><h4>Temuan</h4><p>${esc(d.description||'-')}</p><h4>Saran Perbaikan</h4><p>${esc(d.suggestion||'-')}</p></div></div>
  <div class="qc-ba-section"><div class="qc-ba-title"><div><span class="eyebrow dark">DOKUMENTASI QC</span><h3>Before & After</h3></div><span class="muted">Perbandingan kondisi temuan dan hasil perbaikan</span></div><div class="qc-ba-grid">${qcEvidencePanel('BEFORE',beforeDoc,{date:beforeDate,note:beforeNote,empty:'Foto before belum tersedia'})}${qcEvidencePanel('AFTER',afterDoc,{date:afterDate,note:afterNote,empty:'Foto after belum tersedia'})}</div></div>
  ${extraDocs.length?`<div class="qc-extra-evidence"><h4>Bukti Tambahan</h4><div class="evidence-grid">${extraDocs.map(x=>`<a class="evidence-card" target="_blank" href="/api/documents/${encodeURIComponent(x.id)}/file"><b>${esc(x.data.title||x.data.originalName)}</b><span>${fmtDate(x.data.uploadedAt)}</span></a>`).join('')}</div></div>`:''}
  <h4 style="margin-top:20px">Riwayat Perbaikan</h4>${findingActs.map(x=>`<div class="history-row"><b>${fmtDate(x.data.date)}</b> ${esc(x.data.description||'Hasil perbaikan dikirim')}</div>`).join('')||'<div class="muted">Belum ada perbaikan.</div>'}<h4 style="margin-top:18px">Riwayat Verifikasi</h4>${findingVer.map(x=>`<div class="history-row"><b>${esc(x.data.result)}</b> — ${esc(x.data.note||'-')}</div>`).join('')||'<div class="muted">Belum ada verifikasi.</div>'}`;
  openModal(`Temuan QC — ${d.area||d.item||''}`,`${projectName(d.projectId)} • ${fmtDate(d.date)}`,html,async()=>{});$('.modal')?.classList.add('qc-finding-detail-modal');if($('#modalCancel'))$('#modalCancel').textContent='Tutup';
}

function v31QcAnalyticsHtml(findings){
  const projectRows=state.projects.map(p=>{const rows=findings.filter(x=>x.data.projectId===p.id);return {name:projectDisplayName(p),total:rows.length,open:rows.filter(x=>String(x.data.status).toUpperCase()!=='CLOSED').length,closed:rows.filter(x=>String(x.data.status).toUpperCase()==='CLOSED').length,score:v31QcScore(rows),pm:employeeName(p.data.pmUserId)};}).filter(x=>x.total);
  const months=[];const now=new Date();for(let i=5;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth()-i,1);months.push({key:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`,label:d.toLocaleDateString('id-ID',{month:'short'}),baru:0,selesai:0});}
  for(const r of findings){const m=months.find(x=>String(r.data.date||'').startsWith(x.key));if(m)m.baru++;const c=months.find(x=>String(r.data.closedAt||'').startsWith(x.key));if(c)c.selesai++;}
  const max=Math.max(1,...months.flatMap(x=>[x.baru,x.selesai]));const bars=months.map(x=>`<div class="trend-month"><div class="trend-bars"><i class="trend-new" style="height:${Math.max(3,x.baru/max*80)}px"></i><i class="trend-closed" style="height:${Math.max(3,x.selesai/max*80)}px"></i></div><span>${esc(x.label)}</span><small>${x.baru}/${x.selesai}</small></div>`).join('');
  return `<div class="grid g-2" style="margin-top:16px"><div class="card"><div class="card-head"><div><h3>Temuan per Proyek</h3><p>Open / Closed / QC Score.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Proyek</th><th>Open</th><th>Closed</th><th>QC Score</th></tr></thead><tbody>${projectRows.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${x.open}</td><td>${x.closed}</td><td><b>${x.score}</b></td></tr>`).join('')||'<tr><td colspan="4" class="empty">Belum ada data.</td></tr>'}</tbody></table></div></div><div class="card"><div class="card-head"><div><h3>Tren 6 Bulan</h3><p>Temuan baru / temuan ditutup.</p></div></div><div class="trend-chart">${bars}</div></div></div><div class="card" style="margin-top:16px"><div class="card-head"><div><h3>Performa Project Manager</h3><p>Ringkasan closure temuan pada proyek yang ditangani.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Project Manager</th><th>Proyek</th><th>Selesai</th><th>Total</th><th>QC Score</th></tr></thead><tbody>${projectRows.map(x=>`<tr><td>${esc(x.pm)}</td><td>${esc(x.name)}</td><td>${x.closed}</td><td>${x.total}</td><td><b>${x.score}</b></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Belum ada data.</td></tr>'}</tbody></table></div></div>`;
}
function v31QcStatusText(s){return {'OPEN':'OPEN','ON PROGRESS':'DALAM PERBAIKAN','WAITING QC CHECK':'MENUNGGU VERIFIKASI','REVISION REQUIRED':'REVISION REQUIRED','CLOSED':'CLOSED'}[String(s||'').toUpperCase()]||s||'-';}
function qcSessionStatusPill(status){const s=String(status||'DRAFT').toUpperCase();return s==='DRAFT'?'<span class="qc-session-status running">● Berjalan</span>':'<span class="qc-session-status closed">● Ditutup</span>';}
function qcSessionScoreColor(v){const n=num(v);return n>=90?'var(--success)':n>=70?'var(--warning)':'var(--danger)';}
function qcResultLabel(v){return String(v||'').toUpperCase()==='SESUAI'?'Sesuai':'Tidak sesuai';}
function qcResultClass(v){return String(v||'').toUpperCase()==='SESUAI'?'ok':'bad';}
function qcSessionInspectorName(d){const id=d?.session?.data?.inspectorUserId;const e=state.employees.find(x=>x.id===id);return e?.name||d?.inspectorName||d?.session?.data?.inspectorName||id||'-';}

async function startQcContinuousSession(){
  const preset=state.selectedProjectId||'';
  const today=new Date().toISOString().slice(0,10);
  const html=`<div class="form-grid"><label>Proyek<select name="projectId" required><option value="">Pilih proyek</option>${v31ProjectOptions(preset)}</select></label><label>Tanggal mulai<input type="date" name="date" value="${today}" required></label><label class="span-2">Catatan pemeriksaan<textarea name="note" placeholder="Keterangan umum catatan pemeriksaan proyek ini (opsional)."></textarea></label></div><div class="notice blue"><b>Catatan pemeriksaan bersifat berkelanjutan.</b> Satu proyek cukup satu catatan yang masih berjalan. Sub-pekerjaan dapat ditambah kapan pun selama proyek berlangsung.</div>`;
  openModal('Inspeksi QC Baru','Mulai atau lanjutkan catatan pemeriksaan proyek.',html,async form=>{
    const r=await api('/api/qc/sessions',{method:'POST',body:{projectId:form.projectId.value,date:form.date.value,note:form.note.value}});
    toast(r.continued?'Catatan QC proyek ini masih berjalan. Membuka catatan yang sama.':'Catatan pemeriksaan QC dibuat.');
    setTimeout(()=>openQcContinuousSession(r.id),30);
  });
}

async function openQcContinuousSession(id){
  try{const d=await api(`/api/qc/sessions/${encodeURIComponent(id)}`);renderQcContinuousSession(d);}catch(e){toast(e.message,'err');}
}

function qcSubItemHtml(x,canEdit){
  const d=x.data||{};const bad=String(d.result||'').toUpperCase()==='TIDAK SESUAI';
  const photo=d.evidenceDocumentId?`<a class="qc-photo-link" target="_blank" href="/api/documents/${encodeURIComponent(d.evidenceDocumentId)}/file"><img src="/api/documents/${encodeURIComponent(d.evidenceDocumentId)}/file" alt="Foto inspeksi"></a>`:'<div class="qc-no-photo">Belum ada foto</div>';
  const editButtons=canEdit?`<div class="qc-result-buttons"><button type="button" class="qc-result-btn ok ${!bad?'selected':''}" data-qc-item-result="${esc(x.id)}" data-result="SESUAI" ${d.findingId?'disabled title="Sudah menjadi temuan QC"':''}>Sesuai</button><button type="button" class="qc-result-btn bad ${bad?'selected':''}" data-qc-item-result="${esc(x.id)}" data-result="TIDAK SESUAI">Tidak sesuai</button></div>`:`<span class="qc-result-read ${bad?'bad':'ok'}">${qcResultLabel(d.result)}</span>`;
  return `<div class="qc-subitem ${bad?'bad':''}"><div class="qc-sub-head"><div class="qc-sub-number">•</div><div class="qc-sub-title"><b>${esc(d.item||'-')}</b><span>Diperiksa ${fmtDate(d.date)}</span>${d.findingId?`<span class="finding-link">Diterbitkan sebagai temuan</span>`:''}</div>${canEdit?`<div class="qc-sub-actions"><button type="button" class="btn small" data-qc-item-edit="${esc(x.id)}">Edit</button><button type="button" class="btn small danger" data-qc-item-delete="${esc(x.id)}">Hapus</button></div>`:''}</div>${editButtons}<div class="qc-sub-body">${photo}<div class="qc-sub-detail">${canEdit?`<button type="button" class="btn small" data-qc-item-photo="${esc(x.id)}">${d.evidenceDocumentId?'Ganti foto':'Ambil / pilih foto'}</button><input type="file" class="qc-existing-photo hidden" data-item-id="${esc(x.id)}" accept="image/*"><textarea data-qc-item-note="${esc(x.id)}" placeholder="Keterangan (opsional)">${esc(d.note||'')}</textarea>`:`<p>${esc(d.note||'Tanpa keterangan')}</p>`}</div></div></div>`;
}

function qcGroupHtml(group,items,canEdit,projectId){
  const arr=items.filter(x=>String(x.data.workGroup||'')===String(group.name));
  const sesuai=arr.filter(x=>String(x.data.result||'').toUpperCase()==='SESUAI').length;
  const tidak=arr.filter(x=>String(x.data.result||'').toUpperCase()==='TIDAK SESUAI').length;
  const score=arr.length?Math.round(sesuai/arr.length*100):null;
  const key=`qcg_${String(group.id||group.name).replace(/[^a-zA-Z0-9_-]/g,'_')}`;
  const existing=arr.length?arr.map(x=>qcSubItemHtml(x,canEdit)).join(''):'<div class="qc-empty-group">Belum ada sub-pekerjaan yang dicatat pada bagian ini.</div>';
  const add=canEdit?`<div class="qc-add-box" data-qc-add-box="${esc(key)}"><input class="qc-new-item" placeholder="Uraian sub-pekerjaan, mis. Pembesian kolom K1 lantai 2"><div class="qc-result-buttons qc-new-results"><button type="button" class="qc-result-btn ok" data-qc-new-result="SESUAI">Sesuai</button><button type="button" class="qc-result-btn bad" data-qc-new-result="TIDAK SESUAI">Tidak sesuai</button></div><textarea class="qc-new-note" placeholder="Keterangan (opsional)"></textarea><div class="qc-add-actions"><button type="button" class="btn small" data-qc-new-photo>Ambil / pilih foto</button><input type="file" class="qc-new-file hidden" accept="image/*"><button type="button" class="btn small primary" data-qc-add-sub data-group="${esc(group.name)}">Tambahkan</button></div><div class="qc-photo-preview"></div></div>`:'';
  return `<section class="qc-work-group"><header><b>${esc(group.name)}</b><span>${arr.length} sub-pekerjaan${arr.length?` · ${sesuai} sesuai${tidak?` · <strong>${tidak} tidak sesuai</strong>`:''} · ${score}%`:''}</span></header><div class="qc-work-body">${existing}${add}</div></section>`;
}

function renderQcContinuousSession(d){
  const s=d.session?.data||{};state.qcSessionDetail=d;
  const canEdit=Boolean(d.canEdit);const total=num(s.total), sesuai=num(s.sesuai), tidak=num(s.tidak), score=total?num(s.score):0;
  const unpublished=(d.items||[]).filter(x=>String(x.data.result||'').toUpperCase()==='TIDAK SESUAI'&&!x.data.findingId).length;
  $('.modal')?.classList.add('qc-continuous-modal','qc-custom-foot');
  $('#modalTitle').innerHTML=`Pemeriksaan ${esc(projectName(s.projectId))} ${qcSessionStatusPill(s.status)}`;$('#modalHint').textContent='';
  const groups=(d.groups||[]).map(g=>qcGroupHtml(g,d.items||[],canEdit,s.projectId)).join('');
  const footer=`<div class="qc-continuous-footer">${canEdit&&unpublished?`<button type="button" class="btn primary" id="qcPublishFindings">Terbitkan ${unpublished} temuan</button>`:''}<span class="qc-footer-spacer"></span>${canEdit?'<button type="button" class="btn" id="qcEditSession">Edit catatan</button>':''}${d.canClose&&String(s.status||'').toUpperCase()==='DRAFT'?'<button type="button" class="btn" id="qcCloseSession">Tutup catatan</button>':''}${d.canDelete?'<button type="button" class="btn danger" id="qcDeleteSession">Hapus</button>':''}<button type="button" class="btn" id="qcDismissSession">Tutup</button></div>`;
  $('#modalForm').innerHTML=`<div class="qc-session-kpis"><div class="qc-session-kpi neutral"><span>Sub-pekerjaan</span><b>${total}</b><small>dicatat</small></div><div class="qc-session-kpi good"><span>Sesuai</span><b>${sesuai}</b></div><div class="qc-session-kpi bad"><span>Tidak sesuai</span><b>${tidak}</b></div><div class="qc-session-kpi score"><span>Kesesuaian</span><b style="color:${total?qcSessionScoreColor(score):'var(--warning)'}">${total?score+'%':'–'}</b></div></div><dl class="qc-session-meta"><dt>Proyek</dt><dd>${esc(projectName(s.projectId))}</dd><dt>Mulai</dt><dd>${fmtDate(s.startDate)}</dd><dt>Pemeriksa</dt><dd>${esc(qcSessionInspectorName(d))}</dd>${s.note?`<dt>Catatan</dt><dd>${esc(s.note)}</dd>`:''}</dl>${canEdit?'<div class="qc-continuous-note">Catatan ini <b>berkelanjutan</b> — tambahkan sub-pekerjaan kapan pun ada pekerjaan baru yang diperiksa, tanpa perlu menutupnya. Tiap penambahan wajib memilih <b>Sesuai</b> atau <b>Tidak sesuai</b>, dan tanggalnya tercatat sendiri sehingga laporan periodik hanya memuat pemeriksaan pada periode itu. Tutup catatan hanya bila proyeknya sudah selesai.</div>':''}${groups}${footer}`;
  $('#modalBackdrop').classList.remove('hidden');$('#modalForm').onsubmit=e=>e.preventDefault();
  bindQcContinuousModal(d);
}

function bindQcContinuousModal(d){
  const sessionId=d.session.id;
  $$('.qc-add-box','#modalForm').forEach(box=>{
    let result='';const ok=$('[data-qc-new-result="SESUAI"]',box), bad=$('[data-qc-new-result="TIDAK SESUAI"]',box), file=$('.qc-new-file',box), preview=$('.qc-photo-preview',box);
    [ok,bad].forEach(btn=>btn.onclick=()=>{result=btn.dataset.qcNewResult;ok.classList.toggle('selected',result==='SESUAI');bad.classList.toggle('selected',result==='TIDAK SESUAI');});
    $('[data-qc-new-photo]',box).onclick=()=>file.click();file.onchange=()=>{const f=file.files?.[0];preview.innerHTML=f?`<span class="pill gray">Foto siap: ${esc(f.name)}</span>`:'';};
    $('[data-qc-add-sub]',box).onclick=async e=>{const item=$('.qc-new-item',box).value.trim();if(!item){toast('Isi dulu uraian sub-pekerjaan.','err');return;}if(!result){toast('Pilih dulu Sesuai atau Tidak sesuai.','err');return;}const fd=new FormData();fd.append('workGroup',e.currentTarget.dataset.group);fd.append('item',item);fd.append('result',result);fd.append('note',$('.qc-new-note',box).value);fd.append('date',new Date().toISOString().slice(0,10));if(file.files?.[0])fd.append('file',file.files[0]);try{await api(`/api/qc/sessions/${encodeURIComponent(sessionId)}/items`,{method:'POST',body:fd});toast('Sub-pekerjaan ditambahkan.');await openQcContinuousSession(sessionId);}catch(err){toast(err.message,'err');}};
  });
  $$('[data-qc-item-result]','#modalForm').forEach(b=>b.onclick=async()=>{try{await api(`/api/qc/session-items/${encodeURIComponent(b.dataset.qcItemResult)}`,{method:'PATCH',body:{result:b.dataset.result}});await openQcContinuousSession(sessionId);}catch(e){toast(e.message,'err');}});
  $$('[data-qc-item-note]','#modalForm').forEach(t=>t.onchange=async()=>{try{await api(`/api/qc/session-items/${encodeURIComponent(t.dataset.qcItemNote)}`,{method:'PATCH',body:{note:t.value}});toast('Keterangan tersimpan.');}catch(e){toast(e.message,'err');}});
  $$('[data-qc-item-edit]','#modalForm').forEach(b=>b.onclick=()=>openQcItemEdit(sessionId,(d.items||[]).find(x=>x.id===b.dataset.qcItemEdit)));
  $$('[data-qc-item-delete]','#modalForm').forEach(b=>b.onclick=async()=>{const item=(d.items||[]).find(x=>x.id===b.dataset.qcItemDelete);const linked=item?.data?.findingId;const msg=linked?'Hapus sub-pekerjaan ini? Temuan QC, tugas perbaikan, riwayat verifikasi, dan bukti terkait temuan juga akan dihapus. Audit penghapusan tetap tersimpan.':'Hapus sub-pekerjaan ini dari catatan QC?';if(!(await confirmAsk(msg)))return;try{await api(`/api/qc/session-items/${encodeURIComponent(b.dataset.qcItemDelete)}`,{method:'DELETE'});toast('Sub-pekerjaan QC dihapus.');await openQcContinuousSession(sessionId);}catch(e){toast(e.message,'err');}});
  $$('[data-qc-item-photo]','#modalForm').forEach(b=>b.onclick=()=>{const inp=$(`.qc-existing-photo[data-item-id="${CSS.escape(b.dataset.qcItemPhoto)}"]`,'#modalForm');if(!inp)return;inp.value='';inp.onchange=async()=>{const f=inp.files?.[0];if(!f)return;const fd=new FormData();fd.append('file',f);try{await api(`/api/qc/session-items/${encodeURIComponent(b.dataset.qcItemPhoto)}/photo`,{method:'POST',body:fd});toast('Foto inspeksi disimpan.');await openQcContinuousSession(sessionId);}catch(e){toast(e.message,'err');}};inp.click();});
  if($('#qcPublishFindings'))$('#qcPublishFindings').onclick=()=>openQcPublishFromSession(sessionId);
  if($('#qcEditSession'))$('#qcEditSession').onclick=()=>openQcSessionEdit(d.session);
  if($('#qcCloseSession'))$('#qcCloseSession').onclick=async()=>{if(!(await confirmAsk('Tutup catatan pemeriksaan ini? Setelah ditutup, sub-pekerjaan tidak dapat diubah.')))return;try{await api(`/api/qc/sessions/${encodeURIComponent(sessionId)}/close`,{method:'POST'});toast('Catatan pemeriksaan ditutup.');closeModal();state.cache.clear();await renderQc();}catch(e){toast(e.message,'err');}};
  if($('#qcDeleteSession'))$('#qcDeleteSession').onclick=async()=>{if(!(await confirmAsk('Hapus catatan inspeksi ini beserta sub-pekerjaannya?')))return;try{await api(`/api/qc/sessions/${encodeURIComponent(sessionId)}`,{method:'DELETE'});toast('Catatan inspeksi dihapus.');closeModal();state.cache.clear();await renderQc();}catch(e){toast(e.message,'err');}};
  if($('#qcDismissSession'))$('#qcDismissSession').onclick=closeModal;
}

function openQcPublishFromSession(sessionId){
  const d=state.qcSessionDetail;const s=d?.session?.data||{};const bad=(d?.items||[]).filter(x=>String(x.data.result||'').toUpperCase()==='TIDAK SESUAI'&&!x.data.findingId);if(!bad.length){toast('Semua item Tidak sesuai sudah menjadi temuan.','err');return;}
  const deadline=new Date(Date.now()+7*864e5).toISOString().slice(0,10);const pelaksana=v31AssignedPelaksana(s.projectId);closeModal();
  const html=`<div class="notice blue"><b>${bad.length} sub-pekerjaan Tidak sesuai</b> akan dibuat menjadi ${bad.length} Temuan QC. PIC otomatis Pelaksana Lapangan proyek: <b>${esc(employeeName(pelaksana))}</b>.</div><div class="qc-publish-list">${bad.map((x,i)=>`<div><b>${i+1}. ${esc(x.data.item)}</b><span>${esc(x.data.workGroup)}${x.data.note?' · '+esc(x.data.note):''}</span></div>`).join('')}</div><div class="form-grid"><label>Deadline perbaikan<input name="deadline" type="date" value="${deadline}" required></label><label>Severity<select name="severity"><option>C - MINOR</option><option selected>B - MAYOR</option><option>A - KRITIS</option></select></label><label class="span-2">Saran perbaikan bersama<textarea name="suggestion" placeholder="Berlaku untuk seluruh temuan yang diterbitkan.">Lakukan perbaikan sesuai hasil inspeksi QC dan ajukan bukti hasil perbaikan.</textarea></label></div>`;
  openModal('Terbitkan Temuan dari Inspeksi','Foto dan keterangan inspeksi tetap menjadi bukti pemeriksaan.',html,async form=>{const r=await api(`/api/qc/sessions/${encodeURIComponent(sessionId)}/publish-findings`,{method:'POST',body:{deadline:form.deadline.value,severity:form.severity.value,suggestion:form.suggestion.value}});toast(`${r.count} temuan QC diterbitkan.`);setTimeout(()=>openQcContinuousSession(sessionId),30);});
}

renderQc = async function(){
  const projectQuery=state.selectedProjectId?`?projectId=${encodeURIComponent(state.selectedProjectId)}`:'';
  const [sessionRes,findings]=await Promise.all([api(`/api/qc/sessions${projectQuery}`),loadCollection('defects',Boolean(state.selectedProjectId))]);
  const sessions=sessionRes.rows||[];const today=new Date().toISOString().slice(0,10);const totalSub=sessions.reduce((a,x)=>a+num(x.data.total),0);const sesuai=sessions.reduce((a,x)=>a+num(x.data.sesuai),0);const tidak=sessions.reduce((a,x)=>a+num(x.data.tidak),0);const score=totalSub?Math.round(sesuai/totalSub*100):0;
  const closedRows=findings.filter(x=>String(x.data.status).toUpperCase()==='CLOSED');const closedOnTime=closedRows.filter(x=>!x.data.deadline||!x.data.closedAt||String(x.data.closedAt).slice(0,10)<=String(x.data.deadline)).length;const openFindings=findings.filter(x=>String(x.data.status||'').toUpperCase()!=='CLOSED');const waiting=findings.filter(x=>String(x.data.status||'').toUpperCase()==='WAITING QC CHECK').length;const overdue=openFindings.filter(x=>x.data.deadline&&String(x.data.deadline)<today).length;const attention=openFindings.slice().sort((a,b)=>String(a.data.deadline||'9999').localeCompare(String(b.data.deadline||'9999')));
  const sessionRows=sessions.map(r=>{const d=r.data,sc=num(d.score),draft=String(d.status||'DRAFT').toUpperCase()==='DRAFT';let a=`<button class="btn small" data-qc-session-open="${esc(r.id)}">Buka</button>`;if(cap('qcInspect')&&draft)a+=`<button class="btn small" data-qc-session-edit="${esc(r.id)}">Edit</button>`;if(cap('qcDeleteSession'))a+=`<button class="btn small danger" data-qc-session-delete="${esc(r.id)}">Hapus</button>`;return `<tr><td>${fmtDate(d.startDate)}</td><td><b>${esc(projectName(d.projectId))}</b></td><td>${fmtNum(d.total,0)} dicatat · ${fmtNum(d.sesuai,0)} sesuai${num(d.tidak)?` · <b class="text-danger">${fmtNum(d.tidak,0)} tidak sesuai</b>`:''}</td><td><b style="color:${num(d.total)?qcSessionScoreColor(sc):'var(--muted)'}">${num(d.total)?sc+'%':'–'}</b></td><td>${qcSessionStatusPill(d.status)}</td><td>${esc(state.employees.find(e=>e.id===d.inspectorUserId)?.name||d.inspectorName||d.inspectorUserId||'-')}</td><td class="actions">${a}</td></tr>`;}).join('')||'<tr><td colspan="7" class="empty">Belum ada catatan pemeriksaan QC.</td></tr>';
  const findingRows=findings.map(r=>{const st=String(r.data.status||'OPEN').toUpperCase();let a=`<button class="btn small" data-qc-detail="${r.id}">Detail</button>`;if(cap('qcInspect'))a+=`<button class="btn small" data-qc-finding-edit="${r.id}">Edit</button>`;if(cap('qcDeleteFinding'))a+=`<button class="btn small danger" data-qc-finding-delete="${r.id}">Hapus</button>`;const isPic=r.data.picUserId===state.user.id;if((isPic||['project_manager','manager_operasional','admin_teknik','administrator','direktur','head_unit_bisnis'].includes(state.access.roleKey))&&['OPEN','REVISION REQUIRED'].includes(st))a+=`<button class="btn small" data-qc-action="start" data-id="${r.id}">Mulai</button>`;if((isPic||['project_manager','manager_operasional','admin_teknik','administrator','direktur','head_unit_bisnis'].includes(state.access.roleKey))&&st==='ON PROGRESS')a+=`<button class="btn small primary" data-qc-action="submit-fix" data-id="${r.id}">Kirim Perbaikan</button>`;if(cap('qcVerify')&&st==='WAITING QC CHECK')a+=`<button class="btn small success" data-qc-action="verify" data-id="${r.id}">Verifikasi</button>`;return `<tr><td>${fmtDate(r.data.date)}</td><td>${esc(projectName(r.data.projectId))}</td><td><b>${esc(r.data.area||r.data.item||'-')}</b><div class="tiny muted">${esc(r.data.category||'-')}</div></td><td>${esc(r.data.description||r.data.notes||'-')}</td><td>${statusPill(r.data.severity)}</td><td>${esc(employeeName(r.data.picUserId))}</td><td>${fmtDate(r.data.deadline)}</td><td>${statusPill(v31QcStatusText(st))}</td><td class="actions">${a}</td></tr>`;}).join('')||'<tr><td colspan="9" class="empty">Belum ada temuan QC. Temuan dibuat dari sub-pekerjaan Tidak sesuai atau secara manual.</td></tr>';
  $('#content').innerHTML=`<div class="kpis">${kpi('Catatan Inspeksi',sessions.length,'blue')}${kpi('Sub-pekerjaan',totalSub,'purple')}${kpi('Sesuai',sesuai,'green')}${kpi('Tidak Sesuai',tidak,'red')}${kpi('Kesesuaian',totalSub?score+'%':'–','orange')}${kpi('Total Temuan',findings.length,'orange')}${kpi('Menunggu Verifikasi',waiting,'purple')}${kpi('Overdue',overdue,'red')}</div><div class="notice blue"><b>Alur QC:</b> QC/Head of Supporting membuat inspeksi → item Tidak sesuai diterbitkan menjadi Temuan → Pelaksana melakukan perbaikan → QC/Head of Supporting verifikasi → Closed atau kembali Revision Required. Semua data QC yang masih relevan dapat diedit, dan role QC/Head of Supporting dapat menghapus data QC dengan konfirmasi; audit penghapusan tetap tersimpan.</div><div class="card"><div class="card-head"><div><h3>Inspeksi QC</h3><p>Satu catatan berjalan per proyek. Gunakan tombol Buka untuk menambah sub-pekerjaan; Edit untuk catatan; Hapus untuk menghapus inspeksi beserta data terkait.</p></div>${cap('qcInspect')?'<button class="btn primary" id="qcNewSession">+ Inspeksi Baru</button>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>Mulai</th><th>Proyek</th><th>Sub-pekerjaan</th><th>Kesesuaian</th><th>Status</th><th>Pemeriksa</th><th>Aksi</th></tr></thead><tbody>${sessionRows}</tbody></table></div></div><div class="section-separator"><span>TEMUAN & TINDAK LANJUT QC</span></div><div class="kpis">${kpi('Total Temuan',findings.length,'orange')}${kpi('Open / Perbaikan',openFindings.length,'red')}${kpi('Menunggu Verifikasi',waiting,'purple')}${kpi('Closed On Time',closedOnTime,'green')}${kpi('QC Score',`${v31QcScore(findings)}%`,'blue')}</div><div class="card"><div class="card-head"><div><h3>Temuan QC</h3><p>Edit hanya mengubah informasi temuan. Perpindahan status tetap wajib memakai Mulai → Kirim Perbaikan → Verifikasi agar workflow dan Tugas Saya konsisten.</p></div>${cap('qcInspect')?'<button class="btn primary" id="v31NewFinding">+ Temuan Manual</button>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Proyek</th><th>Area & Kategori</th><th>Temuan</th><th>Severity</th><th>PIC</th><th>Deadline</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${findingRows}</tbody></table></div></div><div class="grid g-2" style="margin-top:16px"><div class="card"><div class="card-head"><div><h3>Tugas Perbaikan Saya</h3><p>Temuan yang PIC-nya adalah akun aktif.</p></div></div><div class="card-body">${findings.filter(x=>x.data.picUserId===state.user.id&&String(x.data.status).toUpperCase()!=='CLOSED').map(x=>`<div class="history-row"><b>${esc(x.data.area||x.data.item||'-')}</b> — ${esc(x.data.description||x.data.notes||'-')} <span class="pill orange">${esc(v31QcStatusText(x.data.status))}</span></div>`).join('')||'<div class="empty">Tidak ada tugas QC/perbaikan aktif.</div>'}</div></div><div class="card"><div class="card-head"><div><h3>Antrean Verifikasi QC</h3><p>Hasil perbaikan yang menunggu pemeriksaan ulang QC.</p></div></div><div class="card-body">${findings.filter(x=>String(x.data.status).toUpperCase()==='WAITING QC CHECK').map(x=>`<div class="history-row"><b>${esc(projectName(x.data.projectId))}</b> — ${esc(x.data.area||x.data.item||'-')} — ${esc(employeeName(x.data.picUserId))}</div>`).join('')||'<div class="empty">Tidak ada antrean verifikasi.</div>'}</div></div></div><div class="card" style="margin-top:16px"><div class="card-head"><div><h3>Perlu Perhatian</h3><p>Temuan terbuka diurutkan berdasarkan deadline.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Proyek</th><th>Temuan</th><th>PIC</th><th>Deadline</th><th>Status</th></tr></thead><tbody>${attention.slice(0,15).map(r=>`<tr><td>${esc(projectName(r.data.projectId))}</td><td>${esc(r.data.description||r.data.item||'-')}</td><td>${esc(employeeName(r.data.picUserId))}</td><td>${fmtDate(r.data.deadline)}</td><td>${statusPill(v31QcStatusText(r.data.status))}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Tidak ada temuan terbuka.</td></tr>'}</tbody></table></div></div>`;
  $('#content').insertAdjacentHTML('beforeend',v31QcAnalyticsHtml(findings));
  if($('#qcNewSession'))$('#qcNewSession').onclick=startQcContinuousSession;
  $$('[data-qc-session-open]').forEach(b=>b.onclick=()=>openQcContinuousSession(b.dataset.qcSessionOpen));
  $$('[data-qc-session-edit]').forEach(b=>b.onclick=()=>openQcSessionEdit(sessions.find(x=>x.id===b.dataset.qcSessionEdit)));
  $$('[data-qc-session-delete]').forEach(b=>b.onclick=()=>deleteQcSessionFromList(sessions.find(x=>x.id===b.dataset.qcSessionDelete)));
  if($('#v31NewFinding'))$('#v31NewFinding').onclick=()=>openQcFindingForm();
  $$('[data-qc-action]').forEach(b=>b.onclick=()=>v31QcAction(b.dataset.id,b.dataset.qcAction));
  $$('[data-qc-detail]').forEach(b=>b.onclick=()=>openQcDetail(findings.find(x=>x.id===b.dataset.qcDetail)));
  $$('[data-qc-finding-edit]').forEach(b=>b.onclick=()=>openQcFindingForm(findings.find(x=>x.id===b.dataset.qcFindingEdit)));
  $$('[data-qc-finding-delete]').forEach(b=>b.onclick=()=>deleteQcFinding(findings.find(x=>x.id===b.dataset.qcFindingDelete)));
};

/* ------------------------------ ATI ------------------------------ */
function v31AtiLevelLabel(l){return {L0:'Kandidat/Buruh Belajar',L1:'Helper Terverifikasi',L2:'Tukang Muda',L3:'Tukang Ahli/Spesialis',L4:'Kepala Tukang',L5:'Mandor/Site Supervisor',L6:'Mitra Usaha ATI'}[l]||l||'-';}
function v31AtiRank(score){const n=num(score);return n>90?'MASTER':n>=80?'SENIOR':n>=70?'MANDIRI':'PEMBINAAN';}
function v31AtiLatestScores(assess){const map=new Map();for(const r of assess.slice().sort((a,b)=>String(a.data.date||'').localeCompare(String(b.data.date||''))))map.set(r.data.workerId,num(r.data.score));return map;}
function v31AtiTrainingTable(training){return `<div class="card"><div class="card-head"><div><h3>Pelatihan</h3><p>Training, hasil kompetensi, sertifikat/bukti, dan remedial.</p></div>${canCollection('pelatihan','create')?'<button class="btn primary" data-add="pelatihan">+ Pelatihan</button>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Peserta</th><th>Pelatihan</th><th>Instruktur</th><th>Hasil</th><th>Status</th><th></th></tr></thead><tbody>${training.map(r=>`<tr><td>${fmtDate(r.data.date)}</td><td>${esc(v31WorkerName(r.data.workerId))}</td><td><b>${esc(r.data.name||'-')}</b></td><td>${esc(r.data.trainer||'-')}</td><td>${esc(r.data.result||'-')}</td><td>${statusPill(r.data.status||'-')}</td><td>${canCollection('pelatihan','update')?`<button class="btn small" data-edit="pelatihan" data-id="${r.id}">Edit</button>`:''}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Belum ada pelatihan.</td></tr>'}</tbody></table></div></div>`;}
function v31AtiLogHtml({att,assess,training,requests,issues}){const logs=[];att.forEach(x=>logs.push({date:x.data.date,type:'KEHADIRAN',text:`${x.data.workerName||v31WorkerName(x.data.workerId)} — ${x.data.attendanceStatus} — ${projectName(x.data.projectId)}`}));assess.forEach(x=>logs.push({date:x.data.date,type:'ASESMEN',text:`${v31WorkerName(x.data.workerId)} — skor ${fmtNum(x.data.score,1)}`}));training.forEach(x=>logs.push({date:x.data.date,type:'PELATIHAN',text:`${v31WorkerName(x.data.workerId)} — ${x.data.name||'-'}`}));requests.forEach(x=>logs.push({date:x.data.date,type:'PENGAJUAN',text:`${x.data.workPackage||'-'} — ${projectName(x.data.projectId)}`}));issues.forEach(x=>logs.push({date:x.data.date,type:'MASALAH',text:`${v31WorkerName(x.data.workerId)} — ${x.data.problem||'-'}`}));logs.sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));return `<div class="card"><div class="card-head"><div><h3>Log ATI</h3><p>Jejak operasional terbaru dari pengajuan, kehadiran, asesmen, pelatihan, dan masalah lapangan.</p></div></div><div class="timeline">${logs.slice(0,60).map(x=>`<div class="history-row"><span class="pill gray">${esc(x.type)}</span> <b>${fmtDate(x.date)}</b> — ${esc(x.text)}</div>`).join('')||'<div class="empty">Belum ada aktivitas.</div>'}</div></div>`;}
async function renderAti(){
  state.v31Workers=await loadCollection('tukang',false);
  const [att,assess,training,requests,issues,evals]=await Promise.all([loadCollection('daily_workers',Boolean(state.selectedProjectId)),loadCollection('ati_assessments',Boolean(state.selectedProjectId)),loadCollection('pelatihan',false),loadCollection('ati_work_requests',Boolean(state.selectedProjectId)),loadCollection('ati_field_issues',Boolean(state.selectedProjectId)),loadCollection('ati_issue_evaluations',Boolean(state.selectedProjectId))]);state.v31AtiIssues=issues;
  const active=state.v31Workers.filter(x=>String(x.data.status||'AKTIF').toUpperCase()==='AKTIF');const today=new Date().toISOString().slice(0,10);const ym=today.slice(0,7);const todayPresent=att.filter(x=>x.data.date===today&&['HADIR','SETENGAH HARI'].includes(String(x.data.attendanceStatus).toUpperCase())).length;const payroll=att.reduce((s,x)=>s+num(x.data.amount),0);const scores=v31AtiLatestScores(assess);const avg=scores.size?[...scores.values()].reduce((a,b)=>a+b,0)/scores.size:0;const joined=state.v31Workers.filter(x=>String(x.data.joinDate||x.data.inputDate||'').startsWith(ym)).length;const exited=state.v31Workers.filter(x=>String(x.data.exitDate||'').startsWith(ym)).length;const available=active.filter(x=>String(x.data.availability||'').toUpperCase()!=='TIDAK TERSEDIA').length;
  const top=active.map(w=>({w,score:scores.get(w.id)??num(w.data.rating)})).sort((a,b)=>b.score-a.score).slice(0,10);
  const levelCounts=['L0','L1','L2','L3','L4','L5','L6'].map(l=>({level:l,count:active.filter(x=>x.data.atiLevel===l).length}));
  const workerTable=`<div class="card"><div class="card-head"><div><h3>Database Tukang</h3><p>Identitas, ATI ID, kategori, Skill 1–3, domisili, ketersediaan, level, tarif, masuk/keluar.</p></div>${canCollection('tukang','create')?'<button class="btn primary" data-add="tukang">+ Tambah Tukang</button>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>ATI ID / Nama</th><th>Usia</th><th>Kategori / Jenis</th><th>Skill</th><th>Domisili</th><th>Ketersediaan</th><th>Level</th><th>Nilai</th><th>Status</th><th></th></tr></thead><tbody>${state.v31Workers.map(r=>{const sc=scores.get(r.id)??num(r.data.rating);return `<tr><td><b>${esc(r.data.name||'-')}</b><div class="tiny muted">${esc(r.data.atiId||'Belum ada ATI ID')} • ${esc(r.data.phone||'')}</div></td><td>${fmtNum(r.data.age,0)}</td><td>${esc(r.data.category||'-')}<div class="tiny muted">${esc(r.data.workerType||'-')}</div></td><td>${esc([r.data.skill1,r.data.skill2,r.data.skill3].filter(Boolean).join(', ')||'-')}</td><td>${esc(r.data.domicile||'-')}</td><td>${esc(r.data.availability||'-')}</td><td><b>${esc(r.data.atiLevel||'-')}</b><div class="tiny muted">${esc(v31AtiLevelLabel(r.data.atiLevel))}</div></td><td><b>${fmtNum(sc,1)}</b><div class="tiny muted">${v31AtiRank(sc)}</div></td><td>${statusPill(r.data.status||'AKTIF')}</td><td>${canCollection('tukang','update')?`<button class="btn small" data-edit="tukang" data-id="${r.id}">Edit</button>`:''}</td></tr>`}).join('')||'<tr><td colspan="10" class="empty">Belum ada data tukang.</td></tr>'}</tbody></table></div></div>`;
  const attendance=`<div class="card"><div class="card-head"><div><h3>Attendance & Productivity / Rekap Upah</h3><p>Otomatis dari Laporan Harian Pelaksana; tidak perlu input absensi ganda.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Proyek</th><th>Tukang</th><th>Status</th><th>Upah</th><th>Lembur</th><th>Total</th></tr></thead><tbody>${att.slice().sort((a,b)=>String(b.data.date).localeCompare(String(a.data.date))).slice(0,120).map(r=>`<tr><td>${fmtDate(r.data.date)}</td><td>${esc(projectName(r.data.projectId))}</td><td>${esc(r.data.workerName||v31WorkerName(r.data.workerId))}</td><td>${statusPill(r.data.attendanceStatus)}</td><td class="num">${fmtRp(r.data.dailyRate)}</td><td>${fmtNum(r.data.overtimeHours)} jam</td><td class="num"><b>${fmtRp(r.data.amount)}</b></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Belum ada data kehadiran.</td></tr>'}</tbody></table></div></div>`;
  const requestTable=`<div class="card"><div class="card-head"><div><h3>Pengajuan Pekerjaan</h3><p>Kebutuhan tenaga ATI untuk proyek/work package.</p></div>${canCollection('ati_work_requests','create')?'<button class="btn primary" data-add="ati_work_requests">+ Pengajuan</button>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Proyek</th><th>Pekerjaan</th><th>Jumlah</th><th>Skill</th><th>Periode</th><th>Status</th><th></th></tr></thead><tbody>${requests.map(r=>`<tr><td>${fmtDate(r.data.date)}</td><td>${r.data.projectId?esc(projectName(r.data.projectId)):'-'}</td><td><b>${esc(r.data.workPackage||'-')}</b></td><td>${fmtNum(r.data.requiredWorkers,0)} ${esc(r.data.workerCategory||'orang')}</td><td>${esc(r.data.requiredSkill||'-')}</td><td>${fmtDate(r.data.startDate)} – ${fmtDate(r.data.endDate)}</td><td>${statusPill(r.data.status)}</td><td>${canCollection('ati_work_requests','update')?`<button class="btn small" data-edit="ati_work_requests" data-id="${r.id}">Edit</button>`:''}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">Belum ada pengajuan pekerjaan.</td></tr>'}</tbody></table></div></div>`;
  const issueTable=`<div class="card"><div class="card-head"><div><h3>Masalah Lapangan</h3><p>Kendala tenaga, penempatan, disiplin, mutu, atau operasional ATI.</p></div>${canCollection('ati_field_issues','create')?'<button class="btn primary" data-add="ati_field_issues">+ Masalah</button>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Proyek</th><th>Tukang</th><th>Masalah</th><th>PIC</th><th>Deadline</th><th>Status</th><th></th></tr></thead><tbody>${issues.map(r=>`<tr><td>${fmtDate(r.data.date)}</td><td>${r.data.projectId?esc(projectName(r.data.projectId)):'-'}</td><td>${esc(v31WorkerName(r.data.workerId))}</td><td>${esc(r.data.problem||'-')}</td><td>${esc(employeeName(r.data.picUserId))}</td><td>${fmtDate(r.data.deadline)}</td><td>${statusPill(r.data.status)}</td><td>${canCollection('ati_field_issues','update')?`<button class="btn small" data-edit="ati_field_issues" data-id="${r.id}">Edit</button>`:''}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">Belum ada masalah lapangan.</td></tr>'}</tbody></table></div></div>`;
  const evalTable=`<div class="card"><div class="card-head"><div><h3>Evaluasi Masalah</h3><p>Akar masalah, tindakan koreksi, dan hasil evaluasi.</p></div>${canCollection('ati_issue_evaluations','create')?'<button class="btn primary" data-add="ati_issue_evaluations">+ Evaluasi</button>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Masalah</th><th>Evaluator</th><th>Akar Masalah</th><th>Solusi</th><th>Status</th><th></th></tr></thead><tbody>${evals.map(r=>{const issue=issues.find(x=>x.id===r.data.issueId);return `<tr><td>${fmtDate(r.data.date)}</td><td>${esc(issue?.data?.problem||r.data.issueId||'-')}</td><td>${esc(employeeName(r.data.evaluatorUserId))}</td><td>${esc(r.data.rootCause||'-')}</td><td>${esc(r.data.resolution||'-')}</td><td>${statusPill(r.data.status)}</td><td>${canCollection('ati_issue_evaluations','update')?`<button class="btn small" data-edit="ati_issue_evaluations" data-id="${r.id}">Edit</button>`:''}</td></tr>`}).join('')||'<tr><td colspan="7" class="empty">Belum ada evaluasi.</td></tr>'}</tbody></table></div></div>`;
  const assessTable=`<div class="card"><div class="card-head"><div><h3>Assessment / Grading</h3><p>Bobot: Quality 40%, Productivity 25%, Discipline 15%, Safety 10%, Teamwork 10%.</p></div>${canCollection('ati_assessments','create')?'<button class="btn primary" id="v31AddAssessment">+ Asesmen</button>':''}</div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Tukang</th><th>Proyek</th><th>Penilai</th><th>Skor</th><th>Grade</th><th>Catatan</th></tr></thead><tbody>${assess.map(r=>`<tr><td>${fmtDate(r.data.date)}</td><td>${esc(v31WorkerName(r.data.workerId))}</td><td>${r.data.projectId?esc(projectName(r.data.projectId)):'-'}</td><td>${esc(employeeName(r.data.assessorUserId))}</td><td><b>${fmtNum(r.data.score,1)}</b></td><td>${statusPill(v31AtiRank(r.data.score))}</td><td>${esc(r.data.notes||'-')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Belum ada asesmen.</td></tr>'}</tbody></table></div></div>`;
  const ranking=`<div class="grid g-2"><div class="card"><div class="card-head"><div><h3>Top 10 Tukang</h3><p>Ranking dari skor asesmen terakhir.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>Nama</th><th>Skill</th><th>Skor</th><th>Grade</th></tr></thead><tbody>${top.map((x,i)=>`<tr><td>${i+1}</td><td><b>${esc(x.w.data.name||'-')}</b></td><td>${esc(x.w.data.skill1||'-')}</td><td><b>${fmtNum(x.score,1)}</b></td><td>${statusPill(v31AtiRank(x.score))}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Belum ada ranking.</td></tr>'}</tbody></table></div></div><div class="card"><div class="card-head"><div><h3>Leveling ATI</h3><p>Distribusi jenjang L0–L6.</p></div></div><div class="card-body">${levelCounts.map(x=>`<div class="bar-row"><span><b>${x.level}</b> ${esc(v31AtiLevelLabel(x.level))}</span><div class="bar-track"><i style="width:${active.length?Math.max(2,x.count/active.length*100):0}%"></i></div><b>${x.count}</b></div>`).join('')}</div></div></div>`;
  $('#content').innerHTML=`<div class="kpis">${kpi('Total Database',state.v31Workers.length,'blue')}${kpi('Aktif',active.length,'green')}${kpi('Available',available,'green')}${kpi('Hadir Hari Ini',todayPresent,'purple')}${kpi('Masuk Bulan Ini',joined,'blue')}${kpi('Keluar Bulan Ini',exited,'red')}${kpi('Total Upah',fmtRp(payroll),'purple')}${kpi('Avg. Performance',fmtNum(avg,1),'orange')}</div><div class="notice blue"><b>Alur ATI:</b> Pendataan → Assessment → Grading → Training → Sertifikasi/Bukti → Penempatan → Monitoring → Career Growth. Attendance dan upah terhubung langsung dari Laporan Harian proyek.</div>${ranking}${requestTable}${workerTable}${attendance}${issueTable}${evalTable}${assessTable}${v31AtiTrainingTable(training)}${v31AtiLogHtml({att,assess,training,requests,issues})}`;
  bindCrudActions();if($('#v31AddAssessment'))$('#v31AddAssessment').onclick=async()=>{state.v31Workers=await loadCollection('tukang',false);openRecordForm('ati_assessments',null,{date:new Date().toISOString().slice(0,10),assessorUserId:state.user.id,projectId:state.selectedProjectId});};
};

