function normalizePositionLabel(value){
  const raw=String(value||'').trim();
  const key=raw.toLowerCase().replace(/[._-]+/g,' ').replace(/\s+/g,' ');
  const map={
    'head operational':'Head of Operational','head operasional':'Head of Operational','manager operasional':'Head of Operational','manajer operasional':'Head of Operational',
    'koordinator engineering':'Head of Engineering','head engineering':'Head of Engineering',
    'koordinator supporting':'Head of Supporting','head supporting':'Head of Supporting',
    'quality control':'QC','qc / quality control':'QC','qc':'QC','senior qc':'QC','qc arsitektur':'QC','qc interior':'QC','qc mep':'QC',
    'site manager':'Project Manager','sm':'Project Manager','superintendent':'Project Manager','site superintendent':'Project Manager','superindtent':'Project Manager',
    'pengawas':'Pelaksana Lapangan','pengawas lapangan':'Pelaksana Lapangan','site supervisor':'Pelaksana Lapangan'
  };
  return map[key]||raw;
}

const V33_POSITION_GROUPS = [
  ['Pimpinan Unit',['Head Unit Bisnis']],
  ['Head Departemen',['Head of Operational','Head of Engineering','Head of Supporting']],
  ['Operasional Proyek',['Project Manager','Pelaksana Lapangan']],
  ['Engineering',['Senior Estimator','Estimator','QS / Quantity Surveyor','Drafter','BIM / BIM Modeller','MEP Engineer','Admin Teknik']],
  ['Supporting / QC',['QC']],
  ['Keuangan / Supply',['Finance','Manager Logistik','Staf Logistik']],
  ['Akademi Tukang Indonesia',['Kepala ATI','Instruktur ATI']],
  ['Akses Sistem',['Administrator','Direktur','Viewer']]
];

renderEmployees = async function(){
  if(!cap('manageEmployees')){$('#content').innerHTML='<div class="notice">Hanya Administrator/Direktur/Head Unit Bisnis yang dapat mengelola karyawan dan akses.</div>';return;}
  const r=await api('/api/records/users');const rows=r.rows||[];
  const matrix=V33_POSITION_GROUPS.map(([g,items])=>`<div class="role-card"><h4>${esc(g)}</h4><p>${items.map(esc).join(' • ')}</p></div>`).join('');
  $('#content').innerHTML=`<div class="notice blue"><b>Role mengikuti posisi/jabatan.</b> Saat karyawan disimpan, posisi yang dipilih sekaligus menjadi role akses. Backend lalu memetakan jabatan itu ke hak akses yang sesuai tanpa perlu memilih role terpisah.</div><div class="role-matrix">${matrix}</div><div class="card" style="margin-top:16px"><div class="card-head"><div><h3>Karyawan & Akun Login</h3><p>Nama pada form proyek/PIC berasal dari daftar ini. Posisi menentukan menu dan kewenangan.</p></div><div class="card-actions"><button class="btn primary" id="addEmployee">+ Tambah Karyawan</button></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Nama</th><th>Username</th><th>Posisi / Jabatan</th><th>Unit/Departemen</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${rows.map(u=>`<tr><td><b>${esc(u.data.name||u.data.username||u.id)}</b><div class="tiny muted">${esc(u.data.email||'')}</div></td><td>${esc(u.data.username||u.id)}</td><td>${statusPill(normalizePositionLabel(u.data.jabatan||u.data.role||'-'))}</td><td>${esc([u.data.unit,u.data.departemen].filter(Boolean).join(' / ')||'-')}</td><td>${statusPill(u.data.status||'Aktif')}</td><td class="actions"><button class="btn small" data-employee-edit="${esc(u.id)}">Edit</button><button class="btn small danger" data-employee-delete="${esc(u.id)}">Hapus</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Belum ada karyawan.</td></tr>'}</tbody></table></div></div>`;
  $('#addEmployee').onclick=()=>openEmployeeForm();$$('[data-employee-edit]').forEach(b=>b.onclick=()=>openEmployeeForm(rows.find(x=>x.id===b.dataset.employeeEdit)));$$('[data-employee-delete]').forEach(b=>b.onclick=async()=>{if(await confirmAsk('Hapus akun karyawan ini?')){await api(`/api/records/users/${encodeURIComponent(b.dataset.employeeDelete)}`,{method:'DELETE'});toast('Karyawan dihapus');await fullRefresh();setView('employees');}});
};

openEmployeeForm = function(row=null){
  const d=row?.data||{};const current=normalizePositionLabel(d.jabatan||d.role||'');const choices=ROLES;
  const html=`<div class="form-grid"><label>Nama Lengkap<input name="name" value="${esc(d.name||'')}" required></label><label>Username<input name="username" value="${esc(d.username||'')}" required></label><label>Email<input type="email" name="email" value="${esc(d.email||'')}"></label><label>No. HP<input name="phone" value="${esc(d.phone||'')}"></label><label class="span-2">Posisi / Jabatan — sekaligus Role Akses<select name="position" required><option value="">Pilih posisi/jabatan</option>${choices.map(x=>`<option value="${esc(x)}" ${x===current?'selected':''}>${esc(x)}</option>`).join('')}</select><span class="field-help">Contoh: Project Manager, Pelaksana Lapangan, Senior Estimator, QC, MEP Engineer, Manager Logistik. Superintendent/Site Manager dipetakan ke Project Manager; Pengawas Lapangan dipetakan ke Pelaksana Lapangan.</span></label><label>Unit<input name="unit" value="${esc(d.unit||'Natara Konstruksi')}"></label><label>Departemen<input name="departemen" value="${esc(d.departemen||'')}"></label><label>Status<select name="status"><option ${String(d.status||'Aktif')==='Aktif'?'selected':''}>Aktif</option><option ${String(d.status||'')==='Nonaktif'?'selected':''}>Nonaktif</option></select></label><label>Password ${row?'<span class="field-help">Kosongkan jika tidak ingin mengganti.</span>':'<span class="field-help">Minimal 6 karakter.</span>'}<input type="password" name="password" ${row?'':'required minlength="6"'}></label></div>`;
  openModal(row?'Edit Karyawan':'Tambah Karyawan','Posisi/Jabatan menjadi role akses; tidak ada lagi role terpisah yang dapat berbeda dari jabatan.',html,async form=>{const position=form.elements.position.value;const data={name:form.elements.name.value,username:form.elements.username.value,email:form.elements.email.value,phone:form.elements.phone.value,role:position,jabatan:position,unit:form.elements.unit.value,departemen:form.elements.departemen.value,status:form.elements.status.value,password:form.elements.password.value};const id=row?.id||data.username||crypto.randomUUID();if(row)await api(`/api/records/users/${encodeURIComponent(id)}`,{method:'PUT',body:data});else await api('/api/records/users',{method:'POST',body:{id,data}});toast('Data karyawan dan role jabatan disimpan');await fullRefresh();setView('employees');});
};

function v33ReportPeriodLabel(d){return `${d.periodType==='MONTHLY'?'Bulanan':'Mingguan'} • ${fmtDate(d.periodStart)} – ${fmtDate(d.periodEnd)}`;}
function v33ReportSummary(type,d){const m=d.snapshot?.metrics||{};return type==='QC'?`Sub ${fmtNum(m.subPekerjaan,0)} • Sesuai ${fmtNum(m.sesuai,0)} • Tidak ${fmtNum(m.tidakSesuai,0)} • Temuan ${fmtNum(m.totalTemuan,0)}`:`Aktif ${fmtNum(m.aktif,0)} • Hadir ${fmtNum(m.hadirPeriode,0)} orang-hari • Upah ${fmtRp(m.totalUpah)} • Avg ${fmtNum(m.avgPerformance,1)}`;}
function v33ReportSection(type,reports){
  const isQc=type==='QC',canCreate=isQc?cap('qcReportCreate'):cap('atiReportCreate');
  const rows=(reports||[]).slice().sort((a,b)=>String(b.data.submittedAt||b.updated_at||'').localeCompare(String(a.data.submittedAt||a.updated_at||'')));
  return `<div class="section-separator"><span>LAPORAN ${type} KE HEAD UNIT BISNIS</span></div><div class="card division-report-card"><div class="card-head"><div><h3>Laporan Mingguan & Bulanan ${type}</h3><p>Isi laporan otomatis mengambil snapshot dari dashboard ${type}. Tombol Edit hanya mengubah judul/catatan pengantar; data snapshot inspeksi/KPI tidak diubah.</p></div>${canCreate?`<div class="card-actions"><button class="btn" data-report-create="${type}" data-period="WEEKLY">+ Mingguan</button><button class="btn primary" data-report-create="${type}" data-period="MONTHLY">+ Bulanan</button></div>`:''}</div><div class="table-wrap"><table class="table"><thead><tr><th>Periode</th><th>Dikirim Oleh</th><th>Ringkasan</th><th>Penerima</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${rows.map(r=>{let a=`<button class="btn small" data-report-detail="${type}" data-id="${esc(r.id)}">Lihat</button>`;if(canCreate)a+=`<button class="btn small" data-report-edit="${type}" data-id="${esc(r.id)}">Edit</button><button class="btn small danger" data-report-delete="${type}" data-id="${esc(r.id)}">Hapus</button>`;if(cap('divisionReportReview')&&String(r.data.status||'').toUpperCase()!=='REVIEWED')a+=`<button class="btn small success" data-report-review="${type}" data-id="${esc(r.id)}">Tandai Dibaca</button>`;return `<tr><td><b>${esc(v33ReportPeriodLabel(r.data))}</b><div class="tiny muted">${esc(r.data.title||'')}</div></td><td>${esc(r.data.submittedByName||employeeName(r.data.submittedByUserId)||'-')}<div class="tiny muted">${fmtDate(String(r.data.submittedAt||'').slice(0,10))}</div></td><td>${esc(v33ReportSummary(type,r.data))}</td><td>${esc(r.data.recipientRole||'Head Unit Bisnis')}</td><td>${statusPill(r.data.status||'SUBMITTED')}</td><td class="actions">${a}</td></tr>`;}).join('')||'<tr><td colspan="6" class="empty">Belum ada laporan yang dikirim.</td></tr>'}</tbody></table></div></div>`;
}
function v349EditDivisionReport(type,row){
  if(!row)return;const d=row.data||{};const html=`<div class="form-grid"><label class="span-2">Judul Laporan<input name="title" value="${esc(d.title||'')}" required></label><label class="span-2">Catatan Pengantar<textarea name="notes">${esc(d.notes||'')}</textarea></label></div><div class="notice blue">Snapshot KPI, inspeksi, temuan, dan data periode tetap terkunci agar laporan tetap sesuai data saat dibuat.</div>`;
  openModal(`Edit Laporan ${type}`,'Edit metadata laporan tanpa mengubah snapshot data.',html,async form=>{await api(`/api/reports/${type.toLowerCase()}/${encodeURIComponent(row.id)}`,{method:'PATCH',body:{title:form.title.value,notes:form.notes.value}});toast(`Laporan ${type} diperbarui.`);state.cache.clear();await renderView();});
}
async function v349DeleteDivisionReport(type,row){
  if(!row)return;if(!(await confirmAsk(`Hapus laporan ${type} periode ${v33ReportPeriodLabel(row.data)}? Tugas review terkait akan dibatalkan dan audit penghapusan tetap tersimpan.`)))return;
  try{await api(`/api/reports/${type.toLowerCase()}/${encodeURIComponent(row.id)}`,{method:'DELETE'});toast(`Laporan ${type} dihapus.`);state.cache.clear();await renderView();}catch(e){toast(e.message,'err');}
}
function v33BindReportActions(type,reports){
  $$(`[data-report-create="${type}"]`).forEach(b=>b.onclick=()=>v33ComposeReport(type,b.dataset.period));
  $$(`[data-report-detail="${type}"]`).forEach(b=>b.onclick=()=>v33OpenReportDetail(type,reports.find(x=>x.id===b.dataset.id)));
  $$(`[data-report-edit="${type}"]`).forEach(b=>b.onclick=()=>v349EditDivisionReport(type,reports.find(x=>x.id===b.dataset.id)));
  $$(`[data-report-delete="${type}"]`).forEach(b=>b.onclick=()=>v349DeleteDivisionReport(type,reports.find(x=>x.id===b.dataset.id)));
  $$(`[data-report-review="${type}"]`).forEach(b=>b.onclick=async()=>{await api(`/api/reports/${type.toLowerCase()}/${encodeURIComponent(b.dataset.id)}/review`,{method:'POST'});toast('Laporan ditandai sudah direview oleh Head Unit Bisnis.');state.cache.clear();await renderView();});
}
function v33ComposeReport(type,periodType){
  const now=new Date().toISOString().slice(0,10);const label=periodType==='MONTHLY'?'Bulanan':'Mingguan';
  const html=`<div class="form-grid"><label>Jenis Laporan<input value="${label}" readonly><input type="hidden" name="periodType" value="${periodType}"></label><label>Tanggal Acuan<input type="date" name="anchorDate" value="${now}" required><span class="field-help">Mingguan otomatis Senin–Minggu. Bulanan otomatis tanggal 1–akhir bulan.</span></label><label class="span-2">Catatan Pengantar ke Head Unit Bisnis<textarea name="notes" placeholder="Contoh: fokus temuan mayor minggu ini, kebutuhan keputusan, atau catatan khusus."></textarea></label></div><div class="notice blue"><b>Otomatis dari data Nara System.</b> Laporan tidak diisi ulang manual. Snapshot dibuat dari data dashboard ${type} pada periode tersebut lalu langsung dikirim ke akun Head Unit Bisnis.</div>`;
  openModal(`Buat & Kirim Laporan ${type} ${label}`,'Penerima otomatis: seluruh akun aktif dengan posisi Head Unit Bisnis.',html,async form=>{await api(`/api/reports/${type.toLowerCase()}/generate`,{method:'POST',body:{periodType:form.periodType.value,anchorDate:form.anchorDate.value,notes:form.notes.value}});toast(`Laporan ${type} ${label.toLowerCase()} berhasil dikirim ke Head Unit Bisnis.`);state.cache.clear();await renderView();});$('#modalSave').textContent='Buat & Kirim';
}
function v33RowsTable(headers,rows,empty='Tidak ada data pada periode ini.'){return `<div class="table-wrap"><table class="table"><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty">${esc(empty)}</td></tr>`}</tbody></table></div>`;}
function v33OpenReportDetail(type,row){if(!row)return;const d=row.data||{},s=d.snapshot||{},m=s.metrics||{};let body='';
  if(type==='QC'){
    const groups=(s.groups||[]).map(x=>`<tr><td>${esc(x.workGroup)}</td><td>${fmtNum(x.total,0)}</td><td>${fmtNum(x.sesuai,0)}</td><td>${fmtNum(x.tidak,0)}</td><td>${x.total?Math.round(num(x.sesuai)/num(x.total)*100):0}%</td></tr>`).join('');
    const inspections=(s.inspections||[]).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.project)}</td><td>${esc(x.workGroup)}</td><td>${esc(x.item)}</td><td>${statusPill(x.result)}</td><td>${esc(x.inspector)}</td><td>${esc(x.note||'-')}</td></tr>`).join('');
    const findings=(s.findings||[]).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.project)}</td><td>${esc(x.area)}</td><td>${esc(x.description)}</td><td>${statusPill(x.severity)}</td><td>${esc(x.pic)}</td><td>${fmtDate(x.deadline)}</td><td>${statusPill(x.status)}</td></tr>`).join('');
    body=`<div class="kpis report-kpis">${kpi('Catatan Inspeksi',m.catatanInspeksi||0,'blue')}${kpi('Sub-pekerjaan',m.subPekerjaan||0,'purple')}${kpi('Sesuai',m.sesuai||0,'green')}${kpi('Tidak Sesuai',m.tidakSesuai||0,'red')}${kpi('Kesesuaian',`${m.kesesuaian||0}%`,'orange')}${kpi('Total Temuan',m.totalTemuan||0,'orange')}${kpi('Open / Perbaikan',m.openPerbaikan||0,'red')}${kpi('Menunggu Verifikasi',m.menungguVerifikasi||0,'purple')}${kpi('Closed On Time',m.closedOnTime||0,'green')}${kpi('Overdue',m.overdue||0,'red')}${kpi('QC Score',`${m.qcScore??100}%`,'blue')}</div><h4>Rekap per Item Pekerjaan</h4>${v33RowsTable(['Item Pekerjaan','Sub','Sesuai','Tidak','Kesesuaian'],groups)}<h4>Rincian Pemeriksaan</h4>${v33RowsTable(['Tanggal','Proyek','Kelompok','Sub-pekerjaan','Hasil','Pemeriksa','Keterangan'],inspections)}<h4>Temuan QC Periode</h4>${v33RowsTable(['Tanggal','Proyek','Area','Temuan','Severity','PIC','Deadline','Status'],findings)}`;
  }else{
    const top=(s.top||[]).map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.name)}</td><td>${esc(x.skill)}</td><td>${esc(x.level)}</td><td><b>${fmtNum(x.score,1)}</b></td></tr>`).join('');
    const levels=(s.levels||[]).map(x=>`<tr><td><b>${esc(x.level)}</b></td><td>${esc(v31AtiLevelLabel(x.level))}</td><td>${fmtNum(x.count,0)}</td></tr>`).join('');
    const requests=(s.requests||[]).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.project)}</td><td>${esc(x.workPackage)}</td><td>${fmtNum(x.requiredWorkers,0)}</td><td>${esc(x.requiredSkill)}</td><td>${statusPill(x.status)}</td></tr>`).join('');
    const attendance=(s.attendance||[]).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.project)}</td><td>${esc(x.worker)}</td><td>${statusPill(x.status)}</td><td>${fmtRp(x.dailyRate)}</td><td>${fmtNum(x.overtimeHours)} jam</td><td>${fmtRp(x.amount)}</td></tr>`).join('');
    const issues=(s.issues||[]).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.project)}</td><td>${esc(x.problem)}</td><td>${esc(x.pic)}</td><td>${fmtDate(x.deadline)}</td><td>${statusPill(x.status)}</td></tr>`).join('');
    const evaluations=(s.evaluations||[]).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.issueId||'-')}</td><td>${esc(x.evaluator)}</td><td>${esc(x.rootCause)}</td><td>${esc(x.resolution)}</td><td>${statusPill(x.status)}</td></tr>`).join('');
    const assessments=(s.assessments||[]).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(v31WorkerName(x.workerId)||x.workerId||'-')}</td><td>${esc(x.project)}</td><td>${esc(x.assessor)}</td><td><b>${fmtNum(x.score,1)}</b></td><td>${esc(x.notes||'-')}</td></tr>`).join('');
    const trainings=(s.training||[]).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(v31WorkerName(x.workerId)||x.workerId||'-')}</td><td>${esc(x.name)}</td><td>${esc(x.trainer)}</td><td>${esc(x.result)}</td><td>${statusPill(x.status)}</td></tr>`).join('');
    body=`<div class="kpis report-kpis">${kpi('Total Database',m.totalDatabase||0,'blue')}${kpi('Aktif',m.aktif||0,'green')}${kpi('Available',m.available||0,'green')}${kpi('Hadir Periode',m.hadirPeriode||0,'purple')}${kpi('Masuk Periode',m.masukPeriode||0,'blue')}${kpi('Keluar Periode',m.keluarPeriode||0,'red')}${kpi('Total Upah',fmtRp(m.totalUpah||0),'purple')}${kpi('Avg. Performance',fmtNum(m.avgPerformance||0,1),'orange')}</div><div class="grid g-2"><div><h4>Top 10 Tukang</h4>${v33RowsTable(['#','Nama','Skill','Level','Skor'],top)}</div><div><h4>Leveling ATI</h4>${v33RowsTable(['Level','Jenjang','Jumlah'],levels)}</div></div><h4>Pengajuan Pekerjaan</h4>${v33RowsTable(['Tanggal','Proyek','Work Package','Jumlah','Skill','Status'],requests)}<h4>Attendance & Productivity / Rekap Upah</h4>${v33RowsTable(['Tanggal','Proyek','Tukang','Status','Upah','Lembur','Total'],attendance)}<h4>Masalah Lapangan</h4>${v33RowsTable(['Tanggal','Proyek','Masalah','PIC','Deadline','Status'],issues)}<h4>Evaluasi Masalah</h4>${v33RowsTable(['Tanggal','ID Masalah','Evaluator','Akar Masalah','Solusi','Status'],evaluations)}<h4>Assessment / Grading</h4>${v33RowsTable(['Tanggal','Tukang','Proyek','Penilai','Skor','Catatan'],assessments)}<h4>Pelatihan</h4>${v33RowsTable(['Tanggal','Peserta','Pelatihan','Instruktur','Hasil','Status'],trainings)}`;
  }
  openModal(d.title||`Laporan ${type}`,`${v33ReportPeriodLabel(d)} • Dikirim ke ${d.recipientRole||'Head Unit Bisnis'} • ${d.status||'SUBMITTED'}`,`<div class="report-detail">${d.notes?`<div class="notice blue"><b>Catatan pengantar:</b> ${esc(d.notes)}</div>`:''}${body}</div>`,async()=>{});$('#modalSave').textContent='Tutup';$('#modalCancel').classList.add('hidden');$('.modal')?.classList.add('report-modal');
}

// Reset footer modal setiap membuka form biasa.
const v33BaseOpenModal=openModal;
openModal=function(title,hint,html,onSubmit){v33BaseOpenModal(title,hint,html,onSubmit);$('#modalSave').textContent='Simpan';$('#modalCancel').classList.remove('hidden');$('.modal')?.classList.remove('report-modal');};

const v33BaseRenderQc=renderQc;
renderQc=async function(){await v33BaseRenderQc();if(!canCollection('qc_reports','read'))return;const reports=await loadCollection('qc_reports',false);$('#content').insertAdjacentHTML('beforeend',v33ReportSection('QC',reports));v33BindReportActions('QC',reports);};
const v33BaseRenderAti=renderAti;
renderAti=async function(){await v33BaseRenderAti();const reports=await loadCollection('ati_reports',false);$('#content').insertAdjacentHTML('beforeend',v33ReportSection('ATI',reports));v33BindReportActions('ATI',reports);};

const v33BaseRenderDashboard=renderDashboard;
renderDashboard=async function(){
  await v33BaseRenderDashboard();
  if(!cap('divisionReportReview'))return;
  const [qcReports,atiReports]=await Promise.all([loadCollection('qc_reports',false),loadCollection('ati_reports',false)]);
  const incoming=[...qcReports.map(r=>({...r,division:'QC'})),...atiReports.map(r=>({...r,division:'ATI'}))].filter(r=>String(r.data.status||'SUBMITTED').toUpperCase()!=='REVIEWED').sort((a,b)=>String(b.data.submittedAt||'').localeCompare(String(a.data.submittedAt||'')));
  $('#content').insertAdjacentHTML('afterbegin',`<div class="card report-inbox" style="margin-bottom:16px"><div class="card-head"><div><h3>Laporan Divisi Masuk</h3><p>Laporan QC dan ATI yang dikirim ke Head Unit Bisnis dan belum ditandai selesai direview.</p></div><span class="pill orange">${incoming.length} menunggu review</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Divisi</th><th>Periode</th><th>Dikirim Oleh</th><th>Ringkasan</th><th>Aksi</th></tr></thead><tbody>${incoming.slice(0,12).map(r=>`<tr><td><b>${r.division}</b></td><td>${esc(v33ReportPeriodLabel(r.data))}</td><td>${esc(r.data.submittedByName||'-')}</td><td>${esc(v33ReportSummary(r.division,r.data))}</td><td class="actions"><button class="btn small" data-inbox-detail="${r.division}" data-id="${r.id}">Lihat</button><button class="btn small success" data-inbox-review="${r.division}" data-id="${r.id}">Tandai Dibaca</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Tidak ada laporan baru.</td></tr>'}</tbody></table></div></div>`);
  $$('[data-inbox-detail]').forEach(b=>{const list=b.dataset.inboxDetail==='QC'?qcReports:atiReports;b.onclick=()=>v33OpenReportDetail(b.dataset.inboxDetail,list.find(x=>x.id===b.dataset.id));});
  $$('[data-inbox-review]').forEach(b=>b.onclick=async()=>{await api(`/api/reports/${b.dataset.inboxReview.toLowerCase()}/${encodeURIComponent(b.dataset.id)}/review`,{method:'POST'});toast('Laporan ditandai sudah direview.');state.cache.clear();await renderDashboard();});
};


/* ========================================================================== */
/* KENDALI V3.4 — Workflow Inbox / Tugas Saya + End-to-End Handoffs           */
/* ========================================================================== */
TITLES.tasks=['Tugas Saya','Tugas otomatis muncul saat pekerjaan dialihkan ke Anda/role Anda. Selesaikan lewat workflow modul sumber agar otomatis berpindah ke PIC berikutnya.'];

function v34RoleCan(...roles){return roles.includes(state.access?.roleKey);}
function v34ProjectData(id){return state.projects.find(p=>String(p.id)===String(id))?.data||{};}
function v34ProjectPm(id){const d=v34ProjectData(id);return d.pmUserId||d.projectManagerUserId||d.siteManagerUserId||d.smUserId||'';}
function v34TaskAssignee(d){if(d.assigneeUserId)return employeeName(d.assigneeUserId);return d.assigneeRoleLabel||d.assigneeRole||'Queue Role';}
function v34DueClass(date,status){if(!date||!['OPEN','IN_PROGRESS'].includes(String(status||'').toUpperCase()))return '';return new Date(date+'T23:59:59').getTime()<Date.now()?'task-overdue':'';}
function v34Age(iso){if(!iso)return '-';const n=Math.max(0,Math.floor((Date.now()-new Date(iso).getTime())/86400000));return n===0?'Hari ini':`${n} hari`;}
function v34Priority(p){const x=String(p||'NORMAL').toUpperCase();return `<span class="task-priority ${x.toLowerCase()}">${esc(x)}</span>`;}

async function refreshTaskBadge(){
  const badge=$('#taskBadge');if(!badge||!canView('tasks'))return;
  try{const r=await api('/api/tasks/my');const n=(r.rows||[]).filter(x=>['OPEN','IN_PROGRESS'].includes(String(x.data.status||'').toUpperCase())).length;badge.textContent=n;badge.classList.toggle('hidden',!n);}catch{badge.classList.add('hidden');}
}
function v34TaskButtons(t){const d=t.data||{};const st=String(d.status||'OPEN').toUpperCase();let html='';const mine=String(d.assigneeUserId||'')===String(state.user?.id||'');const roleQueue=!d.assigneeUserId&&String(d.assigneeRole||'')===String(state.access?.roleKey||'');if(st==='OPEN'&&roleQueue)html+=`<button class="btn small" data-task-action="claim" data-id="${esc(t.id)}">Ambil</button>`;if(st==='OPEN'&&(mine||roleQueue||cap('workflowOversight')))html+=`<button class="btn small" data-task-action="start" data-id="${esc(t.id)}">Mulai</button>`;html+=`<button class="btn small primary" data-task-open="${esc(t.id)}">Buka & Proses</button>`;return html;}
async function v34OpenTask(t){const d=t.data||{};if(d.projectId){state.selectedProjectId=String(d.projectId);populateProjectFilter();$('#globalProjectFilter').value=state.selectedProjectId;}setView(d.targetView||'dashboard');toast(`Tugas: ${d.actionLabel||d.waitingFor||d.title||''}`);}
async function v34TaskAction(id,action){try{await api(`/api/tasks/${encodeURIComponent(id)}/action`,{method:'POST',body:{action}});toast(action==='claim'?'Tugas diambil.':'Tugas dimulai.');await renderTasks();await refreshTaskBadge();}catch(e){toast(e.message,'err');}}
async function renderTasks(){
  const canTeam=cap('workflowOversight');const scope=state.v34TaskScope||'mine';const [active,history]=await Promise.all([api(`/api/tasks/my?scope=${encodeURIComponent(scope)}`),api(`/api/tasks/my?scope=${encodeURIComponent(scope)}&includeDone=true`)]);const rows=active.rows||[];const done=(history.rows||[]).filter(x=>['DONE','CANCELLED'].includes(String(x.data.status||'').toUpperCase())).slice(0,50);
  const critical=rows.filter(x=>String(x.data.priority||'').toUpperCase()==='CRITICAL').length;const overdue=rows.filter(x=>v34DueClass(x.data.dueDate,x.data.status)).length;const inprog=rows.filter(x=>String(x.data.status||'').toUpperCase()==='IN_PROGRESS').length;
  $('#content').innerHTML=`<div class="task-hero"><div><span class="eyebrow">WORKFLOW INBOX</span><h2>${scope==='team'?'Pusat Tugas Aktif':'Tugas Saya'}</h2><p>Ketika satu tahap selesai, Nara System menutup tugas ini dan otomatis membuat tugas berikutnya sesuai alur serta posisi penerima.</p></div>${canTeam?`<div class="segmented"><button class="${scope==='mine'?'active':''}" data-task-scope="mine">Tugas Saya</button><button class="${scope==='team'?'active':''}" data-task-scope="team">Semua Tugas Aktif</button></div>`:''}</div>
  <div class="kpis">${kpi('Tugas Aktif',rows.length,'blue')}${kpi('Sedang Dikerjakan',inprog,'purple')}${kpi('Overdue',overdue,'red')}${kpi('Critical',critical,'orange')}</div>
  <div class="card"><div class="card-head"><div><h3>${scope==='team'?'Semua Workflow Aktif':'Menunggu Tindakan Anda'}</h3><p>Kolom “Menunggu” menunjukkan tindakan yang harus diselesaikan sebelum tugas berpindah.</p></div><button class="btn ghost" id="taskRefresh">↻ Refresh</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Prioritas</th><th>Proyek / Modul</th><th>Tugas</th><th>Saat Ini di</th><th>Menunggu</th><th>Deadline</th><th>Umur</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${rows.map(t=>{const d=t.data||{};return `<tr class="${v34DueClass(d.dueDate,d.status)}"><td>${v34Priority(d.priority)}</td><td><b>${esc(d.projectId?projectName(d.projectId):d.sourceCollection?.toUpperCase()||'-')}</b><div class="tiny muted">${esc(d.targetView||d.sourceCollection||'')}</div></td><td><b>${esc(d.title||'-')}</b><div class="tiny muted">${esc(d.stage||'')}</div></td><td>${esc(v34TaskAssignee(d))}${d.fromUserName?`<div class="tiny muted">dari ${esc(d.fromUserName)}</div>`:''}</td><td>${esc(d.waitingFor||d.actionLabel||'-')}</td><td>${d.dueDate?fmtDate(d.dueDate):'-'}</td><td>${esc(v34Age(d.assignedAt))}</td><td>${statusPill(d.status||'OPEN')}</td><td class="actions">${v34TaskButtons(t)}</td></tr>`}).join('')||'<tr><td colspan="9" class="empty">Tidak ada tugas aktif. Semua handoff Anda sudah selesai.</td></tr>'}</tbody></table></div></div>
  <div class="card"><div class="card-head"><div><h3>Riwayat Tugas Terbaru</h3><p>Jejak handoff yang sudah selesai/dibatalkan.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Proyek</th><th>Tugas</th><th>Status</th><th>Selesai</th><th>Diselesaikan oleh</th></tr></thead><tbody>${done.map(t=>{const d=t.data||{};return `<tr><td>${esc(d.projectId?projectName(d.projectId):'-')}</td><td>${esc(d.title||'-')}<div class="tiny muted">${esc(d.stage||'')}</div></td><td>${statusPill(d.status)}</td><td>${d.completedAt?fmtDate(d.completedAt):'-'}</td><td>${esc(d.completedByName||employeeName(d.completedByUserId)||'-')}</td></tr>`}).join('')||'<tr><td colspan="5" class="empty">Belum ada riwayat.</td></tr>'}</tbody></table></div></div>`;
  $$('[data-task-scope]').forEach(b=>b.onclick=()=>{state.v34TaskScope=b.dataset.taskScope;renderTasks();});if($('#taskRefresh'))$('#taskRefresh').onclick=()=>renderTasks();$$('[data-task-action]').forEach(b=>b.onclick=()=>v34TaskAction(b.dataset.id,b.dataset.taskAction));$$('[data-task-open]').forEach(b=>{const t=rows.find(x=>x.id===b.dataset.taskOpen);b.onclick=()=>v34OpenTask(t);});await refreshTaskBadge();
}

function v34WorkflowButtons(c,r){const d=r.data||{},s=String(d.status||'').toUpperCase(),id=esc(r.id),role=state.access?.roleKey;let x='';
  if(['daily_progress','weekly_progress'].includes(c)){
    if(['DRAFT','RETURNED_TO_FIELD'].includes(s))x+=`<button class="btn small primary" data-v34-action="submit" data-v34-col="${c}" data-id="${id}">Kirim ke PM</button>`;
    if(s==='SUBMITTED_TO_PM'&&(String(v34ProjectPm(d.projectId))===String(state.user.id)||v34RoleCan('manager_operasional','head_unit_bisnis','administrator','direktur')))x+=`<button class="btn small success" data-v34-action="pm-approve" data-v34-col="${c}" data-id="${id}">Approve PM</button><button class="btn small danger" data-v34-action="return-field" data-v34-col="${c}" data-id="${id}">Kembalikan</button>`;
    if(s==='PM_APPROVED'&&v34RoleCan('manager_operasional','head_unit_bisnis','administrator','direktur'))x+=`<button class="btn small success" data-v34-action="operational-review" data-v34-col="${c}" data-id="${id}">Review Final</button>`;
  }
  if(c==='opname'){
    if(['DRAFT','RETURNED_TO_QS'].includes(s))x+=`<button class="btn small primary" data-v34-action="submit" data-v34-col="opname" data-id="${id}">Kirim Engineering</button>`;
    if(s==='SUBMITTED_TO_ENGINEERING'&&v34RoleCan('koordinator_engineering','head_unit_bisnis','administrator','direktur'))x+=`<button class="btn small success" data-v34-action="verify" data-v34-col="opname" data-id="${id}">Verifikasi</button><button class="btn small danger" data-v34-action="return-qs" data-v34-col="opname" data-id="${id}">Kembalikan QS</button>`;
    if(s==='VERIFIED'&&v34RoleCan('admin_teknik','koordinator_engineering','manager_operasional','head_unit_bisnis','administrator','direktur'))x+=`<button class="btn small success" data-v34-action="close" data-v34-col="opname" data-id="${id}">Tutup Opname</button>`;
  }
  if(c==='issues'){
    if(s==='OPEN')x+=`<button class="btn small" data-v34-action="start" data-v34-col="issues" data-id="${id}">Mulai</button>`;
    if(s==='IN PROGRESS')x+=`<button class="btn small primary" data-v34-action="submit-review" data-v34-col="issues" data-id="${id}">Kirim Review</button>`;
    if(s==='WAITING')x+=`<button class="btn small success" data-v34-action="close" data-v34-col="issues" data-id="${id}">Close</button><button class="btn small danger" data-v34-action="return" data-v34-col="issues" data-id="${id}">Revisi</button>`;
  }
  if(c==='retention'){
    if(['OPEN','HOLD'].includes(s))x+=`<button class="btn small primary" data-v34-action="release" data-v34-col="retention" data-id="${id}">Release</button>`;
    if(s==='RELEASED')x+=`<button class="btn small success" data-v34-action="close" data-v34-col="retention" data-id="${id}">Tutup</button>`;
  }
  if(c==='closeout'){
    if(s==='OPEN')x+=`<button class="btn small" data-v34-action="start" data-v34-col="closeout" data-id="${id}">Mulai</button>`;
    if(['OPEN','IN PROGRESS'].includes(s))x+=`<button class="btn small success" data-v34-action="complete" data-v34-col="closeout" data-id="${id}">Selesai</button>`;
  }
  return x;
}
const v34BaseGenericRow=genericRow;
genericRow=function(c,r){
  const d=r.data||{};const date=d.date||d.startDate||d.dueDate||d.plannedDate||d.createdAt||r.updated_at;const title=d.description||d.item||d.name||d.workItem||d.activity||d.problem||d.subject||d.title||d.category||r.id;const person=d.picUserId||d.qsUserId||d.ownerUserId||d.requesterUserId;let val='-';if(d.amount!==undefined)val=fmtRp(d.amount);else if(d.budgetAmount!==undefined)val=fmtRp(d.budgetAmount);else if(d.progress!==undefined)val=`${fmtNum(d.progress)}%`;else if(d.verifiedVolume!==undefined)val=fmtNum(d.verifiedVolume);const status=d.status||d.result||'-';return `<tr><td>${fmtDate(date)}<div class="tiny muted">${esc(r.id)}</div></td><td>${d.projectId?esc(projectName(d.projectId)):'-'}</td><td>${esc(title||'-')}</td><td>${person?esc(employeeName(person)):esc(d.vendor||d.participant||'-')}</td><td class="num">${val}</td><td>${statusPill(status)}</td><td class="actions">${v34WorkflowButtons(c,r)}${canCollection(c,'update')?`<button class="btn small" data-edit="${esc(c)}" data-id="${esc(r.id)}">Edit</button>`:''}${canCollection(c,'delete')?`<button class="btn small danger" data-delete="${esc(c)}" data-id="${esc(r.id)}">Hapus</button>`:''}</td></tr>`;
};
async function v34DoSourceAction(col,id,action){let notes='';if(['return-field','return-qs','return'].includes(action))notes=prompt('Catatan/alasan pengembalian:')||'';let path='';if(['daily_progress','weekly_progress'].includes(col))path=`/api/progress/${col}/${encodeURIComponent(id)}/action`;else if(col==='opname')path=`/api/opname/${encodeURIComponent(id)}/action`;else if(col==='issues')path=`/api/issues/${encodeURIComponent(id)}/action`;else if(['retention','closeout'].includes(col))path=`/api/${col}/${encodeURIComponent(id)}/action`;if(!path)return;try{await api(path,{method:'POST',body:{action,notes}});toast('Tugas selesai dan workflow diteruskan.');state.cache.clear();await renderView();await refreshTaskBadge();}catch(e){toast(e.message,'err');}}
